        ["nw.create"] = new() { ["en"] = "Create profile", ["es"] = "Crear perfil", ["fr"] = "Créer le profil", ["de"] = "Profil erstellen", ["pt"] = "Criar perfil", ["it"] = "Crea profilo", ["ja"] = "プロフィールを作成", ["zh"] = "创建资料", ["hi"] = "प्रोफ़ाइल बनाएँ", ["ar"] = "أنشئ الملف" },
        ["nw.terms"] = new() { ["en"] = "By creating a profile you agree to the Terms of Service — profiles are AI-generated synthetic content, never professional advice; you assume the risks of AI interactions. Full terms: GET /terms · docs/terms.md", ["es"] = "Al crear un perfil aceptas las Condiciones del servicio: los perfiles son contenido sintético generado por IA, nunca asesoramiento profesional; asumes los riesgos de interactuar con una IA. Condiciones completas: GET /terms · docs/terms.md", ["fr"] = "En créant un profil, vous acceptez les Conditions d'utilisation : les profils sont un contenu synthétique généré par IA, jamais un conseil professionnel ; vous assumez les risques des interactions avec une IA. Conditions complètes : GET /terms · docs/terms.md", ["de"] = "Mit dem Erstellen eines Profils stimmst du den Nutzungsbedingungen zu — Profile sind KI-erzeugte synthetische Inhalte und nie eine fachliche Beratung; die Risiken der Interaktion mit einer KI trägst du. Vollständige Bedingungen: GET /terms · docs/terms.md", ["pt"] = "Ao criar um perfil aceita os Termos de Serviço — os perfis são conteúdo sintético gerado por IA, nunca aconselhamento profissional; assume os riscos das interações com IA. Termos completos: GET /terms · docs/terms.md", ["it"] = "Creando un profilo accetti i Termini di servizio: i profili sono contenuti sintetici generati da un'IA, mai una consulenza professionale; ti assumi i rischi delle interazioni con un'IA. Termini completi: GET /terms · docs/terms.md", ["ja"] = "プロフィールを作成すると利用規約に同意したことになります。プロフィールは AI が生成した合成コンテンツであり、専門的な助言では決してありません。AI とのやり取りに伴うリスクはご自身が負います。規約全文：GET /terms · docs/terms.md", ["zh"] = "创建资料即表示你同意服务条款 — 资料是 AI 生成的合成内容，绝非专业建议；与 AI 互动的风险由你承担。完整条款：GET /terms · docs/terms.md", ["hi"] = "प्रोफ़ाइल बनाकर आप सेवा शर्तों से सहमत होते हैं — प्रोफ़ाइल AI-निर्मित सिंथेटिक सामग्री हैं, कभी पेशेवर सलाह नहीं; AI से बातचीत के जोखिम आप उठाते हैं। पूरी शर्तें: GET /terms · docs/terms.md", ["ar"] = "بإنشاء ملف فإنك توافق على شروط الخدمة — الملفات محتوى اصطناعي من إنتاج ذكاء اصطناعي وليست استشارة مهنية بأي حال؛ وتتحمّل مخاطر التفاعل مع الذكاء الاصطناعي. الشروط كاملة: GET /terms · docs/terms.md" },
        ["nw.door"] = new() { ["en"] = "A profile depicts me · Is this genuine?", ["es"] = "Un perfil me representa · ¿Esto es auténtico?", ["fr"] = "Un profil me représente · Est-ce authentique ?", ["de"] = "Ein Profil bildet mich ab · Ist das echt?", ["pt"] = "Um perfil retrata-me · Isto é genuíno?", ["it"] = "Un profilo mi rappresenta · È autentico?", ["ja"] = "自分を描いたプロフィールがある · これは本物か", ["zh"] = "有资料描绘了我 · 这是真的吗？", ["hi"] = "एक प्रोफ़ाइल मुझे दर्शाती है · क्या यह असली है?", ["ar"] = "ملف يصوّرني · هل هذا أصلي؟" },
        ["nw.unreachable"] = new() { ["en"] = "Couldn't reach QRME — is the backend running? ({detail})", ["es"] = "No se pudo conectar con QRME: ¿está el backend en marcha? ({detail})", ["fr"] = "Impossible de joindre QRME — le backend est-il démarré ? ({detail})", ["de"] = "QRME nicht erreichbar — läuft das Backend? ({detail})", ["pt"] = "Não foi possível contactar o QRME — o backend está a correr? ({detail})", ["it"] = "Impossibile raggiungere QRME: il backend è in esecuzione? ({detail})", ["ja"] = "QRME に接続できません。バックエンドは起動していますか？（{detail}）", ["zh"] = "无法连接 QRME — 后端在运行吗？（{detail}）", ["hi"] = "QRME तक नहीं पहुँच सके — क्या बैकएंड चल रहा है? ({detail})", ["ar"] = "تعذّر الوصول إلى QRME — هل الواجهة الخلفية تعمل؟ ({detail})" },
