        ["ns.model.sub"] = new() { ["en"] = "Which LLM powers this profile. Unconfigured providers fall back to the offline stub.", ["es"] = "Qué LLM impulsa este perfil. Los proveedores sin configurar recurren al sustituto sin conexión.", ["fr"] = "Quel LLM anime ce profil. Les fournisseurs non configurés basculent sur le substitut hors ligne.", ["de"] = "Welches LLM dieses Profil antreibt. Nicht eingerichtete Anbieter fallen auf den Offline-Ersatz zurück.", ["pt"] = "Que LLM alimenta este perfil. Os fornecedores não configurados recorrem ao substituto offline.", ["it"] = "Quale LLM alimenta questo profilo. I fornitori non configurati ripiegano sul sostituto offline.", ["ja"] = "このプロフィールを動かす LLM。設定されていない提供元はオフラインの代替に切り替わります。", ["zh"] = "驱动这个资料的大模型。未配置的提供方会退回到离线替代实现。", ["hi"] = "यह प्रोफ़ाइल किस LLM से चलती है। बिना कॉन्फ़िगर किए प्रदाता ऑफ़लाइन विकल्प पर चले जाते हैं।", ["ar"] = "أي نموذج لغوي يشغّل هذا الملف. المزوّدون غير المهيّئين يتراجعون إلى البديل دون اتصال." },
        ["ns.model.effective"] = new() { ["en"] = "Effective now: {name}", ["es"] = "Vigente ahora: {name}", ["fr"] = "En vigueur : {name}", ["de"] = "Jetzt aktiv: {name}", ["pt"] = "Em vigor agora: {name}", ["it"] = "In vigore ora: {name}", ["ja"] = "現在有効：{name}", ["zh"] = "当前生效：{name}", ["hi"] = "अभी प्रभावी: {name}", ["ar"] = "الفعّال الآن: {name}" },
        ["ns.lang"] = new() { ["en"] = "Language", ["es"] = "Idioma", ["fr"] = "Langue", ["de"] = "Sprache", ["pt"] = "Idioma", ["it"] = "Lingua", ["ja"] = "言語", ["zh"] = "语言", ["hi"] = "भाषा", ["ar"] = "اللغة" },
        ["ns.lang.sub"] = new() { ["en"] = "The profile speaks this language everywhere it appears — chat, posts, rooms, robot speech.", ["es"] = "El perfil habla este idioma allí donde aparezca: chat, publicaciones, salas, voz del robot.", ["fr"] = "Le profil parle cette langue partout où il apparaît : discussion, publications, salons, voix du robot.", ["de"] = "Das Profil spricht diese Sprache überall, wo es auftritt — Chat, Beiträge, Räume, Roboterstimme.", ["pt"] = "O perfil fala este idioma onde quer que apareça: conversa, publicações, salas, voz do robô.", ["it"] = "Il profilo parla questa lingua ovunque compaia: chat, post, stanze, voce del robot.", ["ja"] = "プロフィールは現れるあらゆる場所でこの言語を話します — チャット、投稿、ルーム、ロボットの発話。", ["zh"] = "资料在出现的每个地方都说这门语言 — 聊天、帖子、房间、机器人说话。", ["hi"] = "प्रोफ़ाइल जहाँ भी दिखे वहाँ यही भाषा बोलती है — चैट, पोस्ट, कक्ष, रोबोट की आवाज़।", ["ar"] = "يتحدث الملف بهذه اللغة أينما ظهر — في المحادثة والمنشورات والغرف وكلام الروبوت." },
        ["ns.lang.pre"] = new() { ["en"] = "Speak it natively (pre-translate)", ["es"] = "Hablarlo de forma nativa (pretraducir)", ["fr"] = "Le parler nativement (prétraduire)", ["de"] = "Muttersprachlich sprechen (vorübersetzen)", ["pt"] = "Falar nativamente (pré-traduzir)", ["it"] = "Parlarlo in modo nativo (pre-tradurre)", ["ja"] = "その言語で直接話す（事前翻訳）", ["zh"] = "以母语方式说（预先翻译）", ["hi"] = "मूल भाषा में बोलें (पूर्व-अनुवाद)", ["ar"] = "التحدث بها أصلًا (ترجمة مسبقة)" },
        ["ns.lang.pre.sub"] = new() { ["en"] = "Off keeps the original voice — translate selectively below.", ["es"] = "Desactivado conserva la voz original; traduce de forma selectiva abajo.", ["fr"] = "Désactivé conserve la voix d'origine — traduisez de façon sélective ci-dessous.", ["de"] = "Aus behält die ursprüngliche Stimme — unten gezielt übersetzen.", ["pt"] = "Desligado mantém a voz original — traduza seletivamente abaixo.", ["it"] = "Disattivato mantiene la voce originale: traduci in modo selettivo qui sotto.", ["ja"] = "オフにすると元の声のままです。下で必要なものだけ翻訳できます。", ["zh"] = "关闭则保留原声 — 在下面按需翻译。", ["hi"] = "बंद रखने पर मूल आवाज़ बनी रहती है — नीचे चुनकर अनुवाद करें।", ["ar"] = "الإيقاف يبقي الصوت الأصلي — ترجم انتقائيًا أدناه." },
