        ["ns.side.declined"] = new() { ["en"] = "You closed this door. It will not be offered again.", ["es"] = "Cerraste esta puerta. No se volverá a ofrecer.", ["fr"] = "Vous avez fermé cette porte. Elle ne sera plus proposée.", ["de"] = "Du hast diese Tür geschlossen. Sie wird nicht erneut angeboten.", ["pt"] = "Fechaste esta porta. Não voltará a ser oferecida.", ["it"] = "Hai chiuso questa porta. Non verrà più offerta.", ["ja"] = "この扉は閉じました。もう案内しません。", ["zh"] = "你关上了这扇门。不会再次提议。", ["hi"] = "आपने यह दरवाज़ा बंद किया। यह दोबारा नहीं दिखेगा।", ["ar"] = "أغلقتَ هذا الباب. لن يُعرض مرة أخرى." },
