        ["ns.rel.save"] = new() { ["en"] = "Save relationship", ["es"] = "Guardar la relación", ["fr"] = "Enregistrer la relation", ["de"] = "Beziehung speichern", ["pt"] = "Guardar a relação", ["it"] = "Salva la relazione", ["ja"] = "関係を保存", ["zh"] = "保存关系", ["hi"] = "संबंध सहेजें", ["ar"] = "احفظ العلاقة" },
        ["ns.rel.saved"] = new() { ["en"] = "Saved — it now treats you as {type}.", ["es"] = "Guardado: ahora te trata como {type}.", ["fr"] = "Enregistré — il vous traite désormais comme {type}.", ["de"] = "Gespeichert — es behandelt dich jetzt als {type}.", ["pt"] = "Guardado — passa a tratá-lo como {type}.", ["it"] = "Salvato: ora ti tratta come {type}.", ["ja"] = "保存しました。今後あなたを「{type}」として扱います。", ["zh"] = "已保存 — 它现在把你当作{type}。", ["hi"] = "सहेजा गया — अब यह आपको {type} मानता है।", ["ar"] = "حُفظ — صار يعاملك بصفتك {type}." },
        ["ns.mtr"] = new() { ["en"] = "Get help with something", ["es"] = "Pedir ayuda con algo", ["fr"] = "Obtenir de l'aide", ["de"] = "Hilfe zu etwas bekommen", ["pt"] = "Obter ajuda com algo", ["it"] = "Chiedere aiuto per qualcosa", ["ja"] = "困りごとの相談", ["zh"] = "获取帮助", ["hi"] = "किसी बात में मदद लें", ["ar"] = "احصل على مساعدة" },
        ["ns.mtr.lead"] = new() { ["en"] = "Something wrong with the app, your profiles or the platform. No account needed — the person who cannot sign in is the one who most needs this door.", ["es"] = "Algo va mal con la app, tus perfiles o la plataforma. Sin cuenta: quien no puede iniciar sesión es quien más necesita esta puerta.", ["fr"] = "Un problème avec l'application, vos profils ou la plateforme. Sans compte : la personne qui ne peut pas se connecter est celle qui a le plus besoin de cette porte.", ["de"] = "Etwas stimmt nicht mit der App, deinen Profilen oder der Plattform. Kein Konto nötig — wer sich nicht anmelden kann, braucht diese Tür am meisten.", ["pt"] = "Algo errado com a app, os seus perfis ou a plataforma. Sem conta — quem não consegue entrar é quem mais precisa desta porta.", ["it"] = "Qualcosa non va con l'app, i tuoi profili o la piattaforma. Senza account: chi non riesce ad accedere è chi ha più bisogno di questa porta.", ["ja"] = "アプリ・プロフィール・プラットフォームの不具合。アカウントは不要です — サインインできない人こそ、この入口を必要としています。", ["zh"] = "应用、你的形象或平台出了问题。无需账户——登录不了的人最需要这道门。", ["hi"] = "ऐप, आपके प्रोफ़ाइल या प्लैटफ़ॉर्म में कुछ गड़बड़। खाता ज़रूरी नहीं — जो साइन इन नहीं कर पाता, उसे ही यह दरवाज़ा सबसे ज़्यादा चाहिए।", ["ar"] = "خلل في التطبيق أو ملفاتك أو المنصّة. لا حاجة إلى حساب — من لا يستطيع تسجيل الدخول هو أحوج الناس إلى هذا الباب." },
        ["ns.mtr.app"] = new() { ["en"] = "The app", ["es"] = "La app", ["fr"] = "L'application", ["de"] = "Die App", ["pt"] = "A app", ["it"] = "L'app", ["ja"] = "アプリ", ["zh"] = "应用", ["hi"] = "ऐप", ["ar"] = "التطبيق" },
        ["ns.mtr.profiles"] = new() { ["en"] = "My profiles", ["es"] = "Mis perfiles", ["fr"] = "Mes profils", ["de"] = "Meine Profile", ["pt"] = "Os meus perfis", ["it"] = "I miei profili", ["ja"] = "自分のプロフィール", ["zh"] = "我的形象", ["hi"] = "मेरे प्रोफ़ाइल", ["ar"] = "ملفاتي" },
        ["ns.mtr.platform"] = new() { ["en"] = "The platform", ["es"] = "La plataforma", ["fr"] = "La plateforme", ["de"] = "Die Plattform", ["pt"] = "A plataforma", ["it"] = "La piattaforma", ["ja"] = "プラットフォーム", ["zh"] = "平台", ["hi"] = "प्लैटफ़ॉर्म", ["ar"] = "المنصّة" },
        ["ns.mtr.send"] = new() { ["en"] = "Send it", ["es"] = "Enviarlo", ["fr"] = "Envoyer", ["de"] = "Absenden", ["pt"] = "Enviar", ["it"] = "Invia", ["ja"] = "送信する", ["zh"] = "发送", ["hi"] = "भेजें", ["ar"] = "أرسِل" },
        ["ns.mtr.claim"] = new() { ["en"] = "Keep this. It is the only way back to this matter, and it is not shown again.", ["es"] = "Guarda esto. Es la única forma de volver a este asunto, y no se muestra otra vez.", ["fr"] = "Conservez ceci. C'est le seul moyen de retrouver cette affaire, et il ne sera plus affiché.", ["de"] = "Bewahre das auf. Es ist der einzige Weg zurück zu diesem Vorgang, und es wird nicht noch einmal gezeigt.", ["pt"] = "Guarde isto. É a única forma de voltar a este assunto, e não volta a ser mostrado.", ["it"] = "Conserva questo. È l'unico modo per tornare a questa questione, e non verrà mostrato di nuovo.", ["ja"] = "これを控えてください。この案件に戻る唯一の手段で、二度と表示されません。", ["zh"] = "请保存好。这是回到该事项的唯一方式，且不会再次显示。", ["hi"] = "इसे सहेज लें। इस मामले तक लौटने का यही एक रास्ता है, और यह दोबारा नहीं दिखेगा।", ["ar"] = "احتفظ بهذا. إنه السبيل الوحيد للعودة إلى هذه المسألة، ولن يُعرض مرة أخرى." },
        ["ns.mtr.st.open"] = new() { ["en"] = "Waiting", ["es"] = "En espera", ["fr"] = "En attente", ["de"] = "Wartet", ["pt"] = "À espera", ["it"] = "In attesa", ["ja"] = "対応待ち", ["zh"] = "等待中", ["hi"] = "प्रतीक्षा में", ["ar"] = "في الانتظار" },
        ["ns.mtr.st.answered"] = new() { ["en"] = "An answer is waiting on you", ["es"] = "Hay una respuesta esperándote", ["fr"] = "Une réponse vous attend", ["de"] = "Eine Antwort wartet auf dich", ["pt"] = "Há uma resposta à sua espera", ["it"] = "C'è una risposta che ti aspetta", ["ja"] = "回答が届いています", ["zh"] = "有一条回复等你确认", ["hi"] = "एक उत्तर आपकी प्रतीक्षा में है", ["ar"] = "هناك ردّ في انتظارك" },
        ["ns.mtr.st.with_a_person"] = new() { ["en"] = "Somebody has picked it up", ["es"] = "Alguien lo ha tomado", ["fr"] = "Quelqu'un s'en occupe", ["de"] = "Jemand hat es übernommen", ["pt"] = "Alguém pegou nisto", ["it"] = "Qualcuno se ne sta occupando", ["ja"] = "担当者が対応中です", ["zh"] = "已有人接手", ["hi"] = "किसी ने इसे उठाया है", ["ar"] = "تولّاها أحدهم" },
        ["ns.mtr.st.settled"] = new() { ["en"] = "Settled", ["es"] = "Resuelto", ["fr"] = "Réglé", ["de"] = "Erledigt", ["pt"] = "Resolvido", ["it"] = "Risolto", ["ja"] = "解決済み", ["zh"] = "已解决", ["hi"] = "हल हो गया", ["ar"] = "تمّت التسوية" },
        ["ns.mtr.wasit"] = new() { ["en"] = "That was it", ["es"] = "Eso era", ["fr"] = "C'était ça", ["de"] = "Das war es", ["pt"] = "Era isso", ["it"] = "Era quello", ["ja"] = "これで解決しました", ["zh"] = "就是这个", ["hi"] = "यही था", ["ar"] = "كان هذا هو" },
        ["ns.mtr.notit"] = new() { ["en"] = "That was not it", ["es"] = "Eso no era", ["fr"] = "Ce n'était pas ça", ["de"] = "Das war es nicht", ["pt"] = "Não era isso", ["it"] = "Non era quello", ["ja"] = "これではありません", ["zh"] = "不是这个", ["hi"] = "यह नहीं था", ["ar"] = "لم يكن هذا هو" },
        ["ns.mtr.settle"] = new() { ["en"] = "Say what settled it", ["es"] = "Di qué lo resolvió", ["fr"] = "Dites ce qui l'a réglé", ["de"] = "Sag, was es geklärt hat", ["pt"] = "Diga o que o resolveu", ["it"] = "Di' che cosa l'ha risolto", ["ja"] = "何で解決したか書く", ["zh"] = "说明是什么解决了它", ["hi"] = "बताइए इसे किसने हल किया", ["ar"] = "قل ما الذي حسم الأمر" },
        ["ns.mtr.queue"] = new() { ["en"] = "Matters waiting", ["es"] = "Asuntos en espera", ["fr"] = "Affaires en attente", ["de"] = "Wartende Vorgänge", ["pt"] = "Assuntos à espera", ["it"] = "Questioni in attesa", ["ja"] = "対応待ちの案件", ["zh"] = "等待处理的事项", ["hi"] = "प्रतीक्षारत मामले", ["ar"] = "مسائل في الانتظار" },
        ["ns.mtr.take"] = new() { ["en"] = "Take it on", ["es"] = "Tomarlo", ["fr"] = "S'en charger", ["de"] = "Übernehmen", ["pt"] = "Assumir", ["it"] = "Prendilo in carico", ["ja"] = "対応する", ["zh"] = "接手", ["hi"] = "इसे उठाएँ", ["ar"] = "تولَّها" },
        ["ns.mtr.offered"] = new() { ["en"] = "The help box said this, and it is not an answer to your matter:", ["es"] = "La ayuda dijo esto, y no es una respuesta a tu asunto:", ["fr"] = "L'aide a répondu ceci, et ce n'est pas une réponse à votre affaire :", ["de"] = "Die Hilfe sagte dies, und es ist keine Antwort auf deinen Vorgang:", ["pt"] = "A ajuda disse isto, e não é uma resposta ao seu assunto:", ["it"] = "L'aiuto ha detto questo, e non è una risposta alla tua questione:", ["ja"] = "ヘルプはこう答えましたが、あなたの案件への回答ではありません：", ["zh"] = "帮助框这样说，但这不是对你事项的答复：", ["hi"] = "सहायता ने यह कहा, और यह आपके मामले का उत्तर नहीं है:", ["ar"] = "قال مربّع المساعدة هذا، وهو ليس ردًّا على مسألتك:" },
        ["ns.mtr.empty"] = new() { ["en"] = "Nothing raised yet.", ["es"] = "Nada planteado todavía.", ["fr"] = "Rien de signalé pour l'instant.", ["de"] = "Bisher nichts gemeldet.", ["pt"] = "Nada levantado ainda.", ["it"] = "Ancora niente segnalato.", ["ja"] = "まだ何もありません。", ["zh"] = "还没有任何事项。", ["hi"] = "अभी कुछ नहीं उठाया गया।", ["ar"] = "لم يُطرح شيء بعد." },
        ["ns.acc"] = new() { ["en"] = "Accessibility", ["es"] = "Accesibilidad", ["fr"] = "Accessibilité", ["de"] = "Barrierefreiheit", ["pt"] = "Acessibilidade", ["it"] = "Accessibilità", ["ja"] = "アクセシビリティ", ["zh"] = "无障碍", ["hi"] = "सुलभता", ["ar"] = "إمكانية الوصول" },
        ["ns.acc.lead"] = new() { ["en"] = "Ability is not a gate. Three questions — no account, no diagnosis, no name. Your words stay on this deployment and become tracked work.", ["es"] = "La capacidad no es una puerta. Tres preguntas: sin cuenta, sin diagnóstico, sin nombre. Tus palabras se quedan en esta instalación y se convierten en trabajo registrado.", ["fr"] = "La capacité n’est pas une barrière. Trois questions — pas de compte, pas de diagnostic, pas de nom. Vos mots restent sur cette installation et deviennent du travail suivi.", ["de"] = "Fähigkeit ist kein Tor. Drei Fragen — kein Konto, keine Diagnose, kein Name. Deine Worte bleiben auf dieser Installation und werden zu verfolgter Arbeit.", ["pt"] = "Capacidade não é um portão. Três perguntas — sem conta, sem diagnóstico, sem nome. Suas palavras ficam nesta instalação e viram trabalho registrado.", ["it"] = "L’abilità non è un cancello. Tre domande: niente account, niente diagnosi, niente nome. Le tue parole restano su questa installazione e diventano lavoro tracciato.", ["ja"] = "能力は門ではありません。質問は3つ — アカウントも診断名も名前も不要です。あなたの言葉はこの環境にとどまり、追跡される作業になります。", ["zh"] = "能力不是门槛。三个问题——无需账户、无需诊断、无需姓名。你的话留在此部署中，并成为被追踪的工作。", ["hi"] = "क्षमता कोई द्वार नहीं है। तीन प्रश्न — न खाता, न निदान, न नाम। आपके शब्द इसी परिनियोजन में रहते हैं और दर्ज कार्य बन जाते हैं।", ["ar"] = "القدرة ليست بوابة. ثلاثة أسئلة — لا حساب ولا تشخيص ولا اسم. تبقى كلماتك على هذا النشر وتصبح عملًا متتبعًا." },
        ["ns.acc.needs.title"] = new() { ["en"] = "Who is expected here", ["es"] = "A quién esperamos aquí", ["fr"] = "Qui est attendu ici", ["de"] = "Wer hier erwartet wird", ["pt"] = "Quem é esperado aqui", ["it"] = "Chi è atteso qui", ["ja"] = "ここに来ることが想定されている人", ["zh"] = "这里期待谁的到来", ["hi"] = "यहाँ किनकी अपेक्षा है", ["ar"] = "من ننتظر هنا" },
        ["ns.acc.needs.blind"] = new() { ["en"] = "Blind and low-vision: every function works by text, images carry descriptions, and the screens use standard controls a screen reader can walk.", ["es"] = "Personas ciegas o con baja visión: cada función opera por texto, las imágenes llevan descripciones y las pantallas usan controles estándar que un lector de pantalla puede recorrer.", ["fr"] = "Personnes aveugles ou malvoyantes : chaque fonction passe par le texte, les images portent des descriptions et les écrans utilisent des contrôles standard qu’un lecteur d’écran peut parcourir.", ["de"] = "Blinde und sehbehinderte Menschen: jede Funktion geht über Text, Bilder tragen Beschreibungen, und die Oberfläche nutzt Standard-Elemente, die ein Screenreader ablaufen kann.", ["pt"] = "Pessoas cegas ou com baixa visão: toda função opera por texto, as imagens têm descrições e as telas usam controles padrão que um leitor de tela consegue percorrer.", ["it"] = "Persone cieche o ipovedenti: ogni funzione passa dal testo, le immagini hanno descrizioni e le schermate usano controlli standard che uno screen reader può percorrere.", ["ja"] = "全盲・弱視の方：すべての機能はテキストで使え、画像には説明が付き、画面はスクリーンリーダーがたどれる標準コントロールでできています。", ["zh"] = "盲人和低视力者：一切功能都可通过文字完成，图像带有描述，界面使用屏幕阅读器可以遍历的标准控件。", ["hi"] = "दृष्टिहीन और कम दृष्टि वाले: हर कार्य पाठ से होता है, चित्रों के साथ विवरण है, और स्क्रीन में मानक नियंत्रण हैं जिन्हें स्क्रीन रीडर पढ़ सकता है।", ["ar"] = "المكفوفون وضعاف البصر: كل وظيفة تعمل بالنص، والصور تحمل أوصافًا، والشاشات تستخدم عناصر قياسية يستطيع قارئ الشاشة تتبعها." },
        ["ns.acc.needs.deaf"] = new() { ["en"] = "Deaf and hard of hearing: nothing here requires sound — voice is always optional, never the only way.", ["es"] = "Personas sordas o con pérdida auditiva: nada aquí requiere sonido; la voz es siempre opcional, nunca el único camino.", ["fr"] = "Personnes sourdes ou malentendantes : rien ici n’exige de son — la voix est toujours facultative, jamais le seul chemin.", ["de"] = "Gehörlose und schwerhörige Menschen: nichts hier verlangt Ton — Sprache ist immer optional, nie der einzige Weg.", ["pt"] = "Pessoas surdas ou com perda auditiva: nada aqui exige som — a voz é sempre opcional, nunca o único caminho.", ["it"] = "Persone sorde o con perdita d’udito: niente qui richiede l’audio — la voce è sempre facoltativa, mai l’unica via.", ["ja"] = "ろう・難聴の方：ここでは音を必要とするものはありません。音声は常に任意で、唯一の手段になることはありません。", ["zh"] = "聋人和听障者：这里没有任何功能依赖声音——语音永远是可选的，绝不是唯一途径。", ["hi"] = "बधिर और कम सुनने वाले: यहाँ किसी चीज़ के लिए ध्वनि आवश्यक नहीं — आवाज़ हमेशा वैकल्पिक है, कभी एकमात्र रास्ता नहीं।", ["ar"] = "الصم وضعاف السمع: لا شيء هنا يتطلب صوتًا — الصوت اختياري دائمًا، وليس الطريق الوحيد أبدًا." },
        ["ns.acc.needs.mute"] = new() { ["en"] = "Mute and nonspeaking: nothing here requires speaking — anywhere a microphone is offered, typing does the same job.", ["es"] = "Personas mudas o que no hablan: nada aquí requiere hablar; donde se ofrece un micrófono, escribir hace el mismo trabajo.", ["fr"] = "Personnes muettes ou non verbales : rien ici n’exige de parler — partout où un micro est proposé, écrire fait le même travail.", ["de"] = "Stumme und nicht sprechende Menschen: nichts hier verlangt Sprechen — überall, wo ein Mikrofon angeboten wird, tut Tippen denselben Dienst.", ["pt"] = "Pessoas mudas ou não falantes: nada aqui exige falar — onde houver microfone, digitar faz o mesmo trabalho.", ["it"] = "Persone mute o non parlanti: niente qui richiede di parlare — ovunque ci sia un microfono, scrivere fa lo stesso lavoro.", ["ja"] = "発話しない方・発話が難しい方：ここでは話すことを必要とするものはありません。マイクがある場所ではどこでも、入力が同じ役割を果たします。", ["zh"] = "失语和不说话的人：这里没有任何功能要求开口——凡是提供麦克风的地方，打字都能完成同样的事。", ["hi"] = "मूक और न बोलने वाले: यहाँ बोलना आवश्यक नहीं — जहाँ भी माइक्रोफ़ोन है, वहाँ टाइप करना वही काम करता है।", ["ar"] = "البُكم ومن لا يتكلمون: لا شيء هنا يتطلب الكلام — أينما وُجد ميكروفون، تقوم الكتابة بالمهمة نفسها." },
        ["ns.acc.needs.motor"] = new() { ["en"] = "Limited mobility, amputation, tremor: every control is a standard element the keyboard alone can reach, and no step in this console is timed.", ["es"] = "Movilidad reducida, amputación, temblor: cada control es un elemento estándar alcanzable solo con el teclado, y ningún paso de esta consola tiene límite de tiempo.", ["fr"] = "Mobilité réduite, amputation, tremblement : chaque contrôle est un élément standard atteignable au clavier seul, et aucune étape de cette console n’est chronométrée.", ["de"] = "Eingeschränkte Mobilität, Amputation, Tremor: jedes Element ist ein Standard-Element, das die Tastatur allein erreicht, und kein Schritt in dieser Konsole hat ein Zeitlimit.", ["pt"] = "Mobilidade reduzida, amputação, tremor: todo controle é um elemento padrão alcançável só pelo teclado, e nenhum passo neste console é cronometrado.", ["it"] = "Mobilità ridotta, amputazione, tremore: ogni controllo è un elemento standard raggiungibile con la sola tastiera, e nessun passaggio in questa console è a tempo.", ["ja"] = "運動機能の制約・切断・振戦のある方：すべてのコントロールはキーボードだけで届く標準要素で、このコンソールに制限時間のある操作はありません。", ["zh"] = "行动不便、截肢、震颤者：每个控件都是仅用键盘即可到达的标准元素，本控制台没有任何限时步骤。", ["hi"] = "सीमित गतिशीलता, अंग-विच्छेद, कंपन: हर नियंत्रण एक मानक तत्व है जिस तक केवल कीबोर्ड से पहुँचा जा सकता है, और इस कंसोल में कोई चरण समयबद्ध नहीं है।", ["ar"] = "محدودية الحركة والبتر والرُعاش: كل عنصر تحكم قياسي تصل إليه لوحة المفاتيح وحدها، ولا خطوة في هذه الواجهة مقيدة بوقت." },
        ["ns.acc.needs.cognitive"] = new() { ["en"] = "Autistic and cognitively different people: plain words, one step at a time, nothing flashes, and asking again is always free.", ["es"] = "Personas autistas y cognitivamente diversas: palabras llanas, un paso a la vez, nada parpadea, y volver a preguntar es siempre gratis.", ["fr"] = "Personnes autistes et cognitivement différentes : des mots simples, une étape à la fois, rien ne clignote, et redemander est toujours gratuit.", ["de"] = "Autistische und kognitiv verschiedene Menschen: einfache Worte, ein Schritt nach dem anderen, nichts blinkt, und noch einmal fragen kostet nie etwas.", ["pt"] = "Pessoas autistas e cognitivamente diversas: palavras simples, um passo de cada vez, nada pisca, e perguntar de novo é sempre grátis.", ["it"] = "Persone autistiche e cognitivamente diverse: parole semplici, un passo alla volta, niente lampeggia, e chiedere di nuovo non costa mai nulla.", ["ja"] = "自閉スペクトラムの方・認知の仕方が異なる方：平易な言葉、一度にひとつの手順、点滅するものはなく、もう一度尋ねることはいつでも自由です。", ["zh"] = "自闭症和认知方式不同的人：语言平实，一次一步，没有闪烁的内容，再问一遍永远无妨。", ["hi"] = "ऑटिस्टिक और संज्ञानात्मक रूप से भिन्न लोग: सरल शब्द, एक समय में एक कदम, कुछ नहीं चमकता, और दोबारा पूछना हमेशा निःशुल्क है।", ["ar"] = "المصابون بالتوحد والمختلفون إدراكيًا: كلمات بسيطة، خطوة واحدة في كل مرة، لا شيء يومض، والسؤال مرة أخرى مجاني دائمًا." },
        ["ns.acc.needs.dyslexia"] = new() { ["en"] = "Dyslexia and reading differences: short sentences, real headings, and nothing that punishes rereading.", ["es"] = "Dislexia y diferencias de lectura: frases cortas, encabezados reales y nada que castigue releer.", ["fr"] = "Dyslexie et différences de lecture : phrases courtes, vrais titres, et rien qui punisse la relecture.", ["de"] = "Dyslexie und Leseunterschiede: kurze Sätze, echte Überschriften, und nichts bestraft erneutes Lesen.", ["pt"] = "Dislexia e diferenças de leitura: frases curtas, títulos de verdade e nada que puna reler.", ["it"] = "Dislessia e differenze di lettura: frasi brevi, titoli veri e niente che punisca il rileggere.", ["ja"] = "ディスレクシア・読み方の異なる方：短い文、本物の見出し、読み返しても不利にならない画面。", ["zh"] = "阅读障碍者：短句、真实的标题，重读不会受到任何惩罚。", ["hi"] = "डिस्लेक्सिया और पढ़ने की भिन्नताएँ: छोटे वाक्य, वास्तविक शीर्षक, और दोबारा पढ़ने पर कोई दंड नहीं।", ["ar"] = "عسر القراءة وفروق القراءة: جمل قصيرة وعناوين حقيقية ولا شيء يعاقب على إعادة القراءة." },
        ["ns.acc.needs.motion"] = new() { ["en"] = "Motion sensitivity: when your device asks for reduced motion, this console stops animating.", ["es"] = "Sensibilidad al movimiento: cuando tu dispositivo pide movimiento reducido, esta consola deja de animar.", ["fr"] = "Sensibilité au mouvement : quand votre appareil demande une animation réduite, cette console cesse d’animer.", ["de"] = "Bewegungsempfindlichkeit: wenn dein Gerät reduzierte Bewegung verlangt, hört diese Konsole auf zu animieren.", ["pt"] = "Sensibilidade a movimento: quando seu dispositivo pede movimento reduzido, este console para de animar.", ["it"] = "Sensibilità al movimento: quando il tuo dispositivo chiede movimento ridotto, questa console smette di animare.", ["ja"] = "動きに敏感な方：端末が「視差効果を減らす」を求めると、このコンソールはアニメーションを止めます。", ["zh"] = "对动态敏感者：当你的设备要求减少动态效果时，本控制台会停止动画。", ["hi"] = "गति के प्रति संवेदनशीलता: जब आपका उपकरण कम गति माँगता है, यह कंसोल एनिमेशन बंद कर देता है।", ["ar"] = "الحساسية للحركة: عندما يطلب جهازك تقليل الحركة، تتوقف هذه الواجهة عن التحريك." },
        ["ns.acc.needs.more"] = new() { ["en"] = "Not on this list? The gap is in the list, not in you. Name it below and it becomes our work.", ["es"] = "¿No estás en esta lista? El vacío está en la lista, no en ti. Nómbralo abajo y se convierte en nuestro trabajo.", ["fr"] = "Pas sur cette liste ? Le manque est dans la liste, pas en vous. Nommez-le ci-dessous et cela devient notre travail.", ["de"] = "Nicht auf dieser Liste? Die Lücke ist in der Liste, nicht in dir. Benenne sie unten, und sie wird unsere Arbeit.", ["pt"] = "Não está nesta lista? A lacuna está na lista, não em você. Nomeie-a abaixo e ela vira nosso trabalho.", ["it"] = "Non sei in questa lista? La lacuna è nella lista, non in te. Nominala qui sotto e diventa il nostro lavoro.", ["ja"] = "この一覧にありませんか？足りないのは一覧であって、あなたではありません。下で名前を付けてください。それが私たちの仕事になります。", ["zh"] = "不在这份清单上？缺的是清单，不是你。在下方写出来，它就成为我们的工作。", ["hi"] = "इस सूची में नहीं हैं? कमी सूची में है, आप में नहीं। नीचे उसे नाम दें और वह हमारा काम बन जाएगा।", ["ar"] = "لست في هذه القائمة؟ النقص في القائمة لا فيك. اذكره أدناه وسيصبح عملنا." },
        ["ns.acc.doing.ph"] = new() { ["en"] = "What were you trying to do?", ["es"] = "¿Qué intentabas hacer?", ["fr"] = "Qu’essayiez-vous de faire ?", ["de"] = "Was hast du versucht zu tun?", ["pt"] = "O que você estava tentando fazer?", ["it"] = "Cosa stavi cercando di fare?", ["ja"] = "何をしようとしていましたか？", ["zh"] = "你当时想做什么？", ["hi"] = "आप क्या करने की कोशिश कर रहे थे?", ["ar"] = "ما الذي كنت تحاول فعله؟" },
        ["ns.acc.wall.ph"] = new() { ["en"] = "What stood in the way?", ["es"] = "¿Qué se interpuso?", ["fr"] = "Qu’est-ce qui a fait obstacle ?", ["de"] = "Was stand im Weg?", ["pt"] = "O que ficou no caminho?", ["it"] = "Cosa ti ha ostacolato?", ["ja"] = "何が妨げになりましたか？", ["zh"] = "是什么挡住了你？", ["hi"] = "क्या आड़े आया?", ["ar"] = "ما الذي وقف في الطريق؟" },
        ["ns.acc.help.ph"] = new() { ["en"] = "What would help? (optional)", ["es"] = "¿Qué ayudaría? (opcional)", ["fr"] = "Qu’est-ce qui aiderait ? (facultatif)", ["de"] = "Was würde helfen? (optional)", ["pt"] = "O que ajudaria? (opcional)", ["it"] = "Cosa aiuterebbe? (facoltativo)", ["ja"] = "何があれば助かりますか？（任意）", ["zh"] = "什么会有帮助？（可选）", ["hi"] = "क्या मदद करेगा? (वैकल्पिक)", ["ar"] = "ما الذي قد يساعد؟ (اختياري)" },
        ["ns.acc.send"] = new() { ["en"] = "Send report", ["es"] = "Enviar informe", ["fr"] = "Envoyer le signalement", ["de"] = "Bericht senden", ["pt"] = "Enviar relato", ["it"] = "Invia la segnalazione", ["ja"] = "報告を送る", ["zh"] = "发送报告", ["hi"] = "रिपोर्ट भेजें", ["ar"] = "أرسل البلاغ" },
        ["ns.acc.sent"] = new() { ["en"] = "Received — thank you.", ["es"] = "Recibido. Gracias.", ["fr"] = "Reçu — merci.", ["de"] = "Angekommen — danke.", ["pt"] = "Recebido — obrigado.", ["it"] = "Ricevuto — grazie.", ["ja"] = "受け取りました。ありがとうございます。", ["zh"] = "已收到——谢谢。", ["hi"] = "प्राप्त हुआ — धन्यवाद।", ["ar"] = "وصل البلاغ — شكرًا لك." },
        ["ns.acc.token.ph"] = new() { ["en"] = "Reviewer token", ["es"] = "Token de revisor", ["fr"] = "Jeton de réviseur", ["de"] = "Prüfer-Token", ["pt"] = "Token de revisor", ["it"] = "Token del revisore", ["ja"] = "レビュアートークン", ["zh"] = "审阅者令牌", ["hi"] = "समीक्षक टोकन", ["ar"] = "رمز المراجع" },
        ["ns.acc.load"] = new() { ["en"] = "Load reports", ["es"] = "Cargar informes", ["fr"] = "Charger les signalements", ["de"] = "Berichte laden", ["pt"] = "Carregar relatos", ["it"] = "Carica le segnalazioni", ["ja"] = "報告を読み込む", ["zh"] = "载入报告", ["hi"] = "रिपोर्टें लोड करें", ["ar"] = "حمّل البلاغات" },
        ["ns.acc.none"] = new() { ["en"] = "No reports yet.", ["es"] = "Aún no hay informes.", ["fr"] = "Aucun signalement pour l’instant.", ["de"] = "Noch keine Berichte.", ["pt"] = "Ainda não há relatos.", ["it"] = "Ancora nessuna segnalazione.", ["ja"] = "まだ報告はありません。", ["zh"] = "还没有报告。", ["hi"] = "अभी कोई रिपोर्ट नहीं।", ["ar"] = "لا بلاغات بعد." },
        ["ns.fb"] = new() { ["en"] = "Help us improve", ["es"] = "Ayúdanos a mejorar", ["fr"] = "Aidez-nous à nous améliorer", ["de"] = "Hilf uns, besser zu werden", ["pt"] = "Ajude-nos a melhorar", ["it"] = "Aiutaci a migliorare", ["ja"] = "改善にご協力ください", ["zh"] = "帮助我们改进", ["hi"] = "हमें बेहतर बनाने में मदद करें", ["ar"] = "ساعدنا على التحسّن" },
        ["ns.fb.sub"] = new() { ["en"] = "Tell us how to make this better — an idea, a rough edge, a bug, or what you love. It goes straight to the team.", ["es"] = "Dinos cómo mejorar esto: una idea, una aspereza, un fallo o lo que te encanta. Va directo al equipo.", ["fr"] = "Dites-nous comment améliorer ceci : une idée, un point rugueux, un bogue, ou ce que vous aimez. Cela va droit à l'équipe.", ["de"] = "Sag uns, wie das besser wird — eine Idee, eine raue Kante, ein Fehler, oder was dir gefällt. Es geht direkt ans Team.", ["pt"] = "Diga-nos como melhorar isto: uma ideia, uma aspereza, um erro, ou o que adora. Vai direto para a equipa.", ["it"] = "Dicci come migliorare questo: un'idea, una ruvidezza, un difetto, o ciò che ami. Va dritto al team.", ["ja"] = "よくする方法を教えてください — 思いつき、引っかかり、不具合、気に入っている点。そのままチームに届きます。", ["zh"] = "告诉我们怎样能更好 — 一个想法、一处别扭、一个缺陷，或者你喜欢的地方。直接送到团队手上。", ["hi"] = "बताइए इसे बेहतर कैसे करें — कोई विचार, कोई खुरदुरापन, कोई ख़राबी, या जो आपको पसंद है। यह सीधे टीम तक जाता है।", ["ar"] = "أخبرنا كيف نحسّن هذا — فكرة، أو نتوء مزعج، أو خلل، أو ما يعجبك. يصل إلى الفريق مباشرة." },
        ["ns.fb.cat"] = new() { ["en"] = "Category", ["es"] = "Categoría", ["fr"] = "Catégorie", ["de"] = "Kategorie", ["pt"] = "Categoria", ["it"] = "Categoria", ["ja"] = "分類", ["zh"] = "类别", ["hi"] = "श्रेणी", ["ar"] = "الفئة" },
        ["ns.fb.msg.ph"] = new() { ["en"] = "What's on your mind?", ["es"] = "¿Qué tienes en mente?", ["fr"] = "Qu'avez-vous en tête ?", ["de"] = "Was beschäftigt dich?", ["pt"] = "O que tem em mente?", ["it"] = "Che cosa hai in mente?", ["ja"] = "思っていることをどうぞ", ["zh"] = "你在想什么？", ["hi"] = "आपके मन में क्या है?", ["ar"] = "ما الذي يدور في بالك؟" },
        ["ns.fb.rating.opt"] = new() { ["en"] = "Rating (optional)", ["es"] = "Valoración (opcional)", ["fr"] = "Note (facultative)", ["de"] = "Bewertung (optional)", ["pt"] = "Avaliação (opcional)", ["it"] = "Valutazione (facoltativa)", ["ja"] = "評価（任意）", ["zh"] = "评分（可选）", ["hi"] = "रेटिंग (वैकल्पिक)", ["ar"] = "التقييم (اختياري)" },
        ["ns.fb.send"] = new() { ["en"] = "Send feedback", ["es"] = "Enviar comentarios", ["fr"] = "Envoyer le retour", ["de"] = "Rückmeldung senden", ["pt"] = "Enviar comentários", ["it"] = "Invia il riscontro", ["ja"] = "フィードバックを送る", ["zh"] = "发送反馈", ["hi"] = "प्रतिक्रिया भेजें", ["ar"] = "أرسل الملاحظات" },
        ["ns.fb.mine"] = new() { ["en"] = "Yours", ["es"] = "Lo tuyo", ["fr"] = "Les vôtres", ["de"] = "Deine", ["pt"] = "Os seus", ["it"] = "I tuoi", ["ja"] = "あなたの投稿", ["zh"] = "你的", ["hi"] = "आपके", ["ar"] = "ما أرسلتَه" },
        ["prob.server"] = new() { ["en"] = "What has reached the server", ["es"] = "Lo que ha llegado al servidor", ["fr"] = "Ce qui a atteint le serveur", ["de"] = "Was den Server erreicht hat", ["pt"] = "O que chegou ao servidor", ["it"] = "Cosa è arrivato al server", ["ja"] = "サーバーに届いたもの", ["zh"] = "已到达服务器的内容", ["hi"] = "सर्वर तक क्या पहुँचा", ["ar"] = "ما وصل إلى الخادم" },
        ["prob.key.ph"] = new() { ["en"] = "the problems key, if this deployment set one", ["es"] = "la clave de problemas, si esta instalación fijó una", ["fr"] = "la clé des problèmes, si ce déploiement en a défini une", ["de"] = "der Problems-Schlüssel, falls diese Installation einen gesetzt hat", ["pt"] = "a chave de problemas, se esta instalação definiu uma", ["it"] = "la chiave dei problemi, se questa installazione ne ha una", ["ja"] = "この配備で設定されていれば、その「problems」キー", ["zh"] = "如果此部署设置了问题密钥，请输入", ["hi"] = "समस्याओं की कुंजी, अगर इस परिनियोजन ने कोई रखी है", ["ar"] = "مفتاح المشاكل، إن كان هذا النشر قد عيّن واحدًا" },
        ["prob.fetch"] = new() { ["en"] = "Read the aggregate", ["es"] = "Leer el agregado", ["fr"] = "Lire l'agrégat", ["de"] = "Das Aggregat lesen", ["pt"] = "Ler o agregado", ["it"] = "Leggi l'aggregato", ["ja"] = "集計を読む", ["zh"] = "读取汇总", ["hi"] = "समग्र पढ़ें", ["ar"] = "اقرأ المجمّع" },
        ["prob.none"] = new() { ["en"] = "Nothing has been reported to this server yet.", ["es"] = "Aún no se ha informado nada a este servidor.", ["fr"] = "Rien n'a encore été rapporté à ce serveur.", ["de"] = "Diesem Server wurde noch nichts gemeldet.", ["pt"] = "Ainda nada foi comunicado a este servidor.", ["it"] = "A questo server non è ancora stato segnalato nulla.", ["ja"] = "このサーバーにはまだ何も報告されていません。", ["zh"] = "尚未有任何报告到达此服务器。", ["hi"] = "इस सर्वर को अभी तक कुछ नहीं बताया गया।", ["ar"] = "لم يُبلَّغ هذا الخادم بشيء بعد." },
        ["ns.pr"] = new() { ["en"] = "When something breaks", ["es"] = "Cuando algo falla", ["fr"] = "Quand quelque chose casse", ["de"] = "Wenn etwas kaputtgeht", ["pt"] = "Quando algo falha", ["it"] = "Quando qualcosa si rompe", ["ja"] = "何かが壊れたとき", ["zh"] = "出问题的时候", ["hi"] = "जब कुछ टूटे", ["ar"] = "حين يتعطّل شيء" },
        ["ns.pr.nowhere"] = new() { ["en"] = "This build reports nowhere. Failures are counted on this device and never leave it.", ["es"] = "Esta compilación no informa a ninguna parte. Los fallos se cuentan en este dispositivo y nunca salen de él.", ["fr"] = "Cette version ne signale rien nulle part. Les échecs sont comptés sur cet appareil et n'en sortent jamais.", ["de"] = "Dieser Build meldet nirgendwohin. Fehler werden auf diesem Gerät gezählt und verlassen es nie.", ["pt"] = "Esta compilação não reporta a lado nenhum. As falhas são contadas neste dispositivo e nunca saem dele.", ["it"] = "Questa build non segnala da nessuna parte. Gli errori sono contati su questo dispositivo e non lo lasciano mai.", ["ja"] = "このビルドはどこにも報告しません。失敗はこの端末で数えられ、端末の外に出ることはありません。", ["zh"] = "这个版本不向任何地方上报。失败只在本机计数，永远不会离开这台设备。", ["hi"] = "यह बिल्ड कहीं रिपोर्ट नहीं करता। विफलताएँ इसी डिवाइस पर गिनी जाती हैं और कभी बाहर नहीं जातीं।", ["ar"] = "هذه النسخة لا ترسل تقارير إلى أي جهة. تُحصى الإخفاقات على هذا الجهاز ولا تغادره أبدًا." },
        ["ns.pr.explain"] = new() { ["en"] = "This app can send a count of what failed — the operation and the HTTP status, the day it happened, and how many times. Not what you typed, not who you are, not which profile. Nothing that identifies you or anyone else.", ["es"] = "Esta app puede enviar un recuento de lo que falló: la operación y el estado HTTP, el día en que ocurrió y cuántas veces. No lo que escribiste, no quién eres, no qué perfil. Nada que te identifique a ti ni a nadie.", ["fr"] = "Cette application peut envoyer un décompte de ce qui a échoué : l'opération et le statut HTTP, le jour où c'est arrivé, et combien de fois. Pas ce que vous avez saisi, pas qui vous êtes, pas quel profil. Rien qui vous identifie, ni personne d'autre.", ["de"] = "Diese App kann eine Zählung des Fehlgeschlagenen senden — den Vorgang und den HTTP-Status, den Tag und wie oft. Nicht, was du getippt hast, nicht, wer du bist, nicht, welches Profil. Nichts, was dich oder sonst jemanden identifiziert.", ["pt"] = "Esta aplicação pode enviar uma contagem do que falhou: a operação e o estado HTTP, o dia em que aconteceu e quantas vezes. Não o que escreveu, não quem é, não qual perfil. Nada que o identifique a si nem a ninguém.", ["it"] = "Questa app può inviare un conteggio di ciò che è fallito: l'operazione e lo stato HTTP, il giorno in cui è accaduto e quante volte. Non ciò che hai scritto, non chi sei, non quale profilo. Nulla che identifichi te o chiunque altro.", ["ja"] = "このアプリは、失敗の件数を送ることができます — 操作と HTTP ステータス、起きた日、そして回数です。入力した内容も、あなたが誰かも、どのプロフィールかも送りません。あなたや他の誰かを特定するものは何も含みません。", ["zh"] = "这个应用可以发送失败的计数 — 操作与 HTTP 状态、发生的日期、以及次数。不包括你输入的内容、你是谁、用的哪个资料。没有任何能指认你或别人的东西。", ["hi"] = "यह ऐप विफलताओं की गिनती भेज सकता है — कौन-सा कार्य और HTTP स्थिति, किस दिन हुआ, और कितनी बार। आपने क्या लिखा, आप कौन हैं, कौन-सी प्रोफ़ाइल — ये नहीं। कुछ भी ऐसा नहीं जो आपकी या किसी की पहचान बताए।", ["ar"] = "يمكن لهذا التطبيق أن يرسل عددًا لما أخفق — العملية وحالة HTTP، واليوم الذي وقع فيه، وكم مرة. لا ما كتبته، ولا من أنت، ولا أي ملف. لا شيء يعرّفك أو يعرّف أحدًا غيرك." },
        ["ns.pr.send"] = new() { ["en"] = "Send counts", ["es"] = "Enviar los recuentos", ["fr"] = "Envoyer les décomptes", ["de"] = "Zählungen senden", ["pt"] = "Enviar as contagens", ["it"] = "Invia i conteggi", ["ja"] = "件数を送る", ["zh"] = "发送计数", ["hi"] = "गिनती भेजें", ["ar"] = "أرسل الأعداد" },
        ["ns.pr.dont"] = new() { ["en"] = "Do not send", ["es"] = "No enviar", ["fr"] = "Ne pas envoyer", ["de"] = "Nicht senden", ["pt"] = "Não enviar", ["it"] = "Non inviare", ["ja"] = "送らない", ["zh"] = "不要发送", ["hi"] = "मत भेजें", ["ar"] = "لا ترسل" },
        ["ns.pr.toggle"] = new() { ["en"] = "Send failure counts", ["es"] = "Enviar recuentos de fallos", ["fr"] = "Envoyer les décomptes d'échecs", ["de"] = "Fehlerzählungen senden", ["pt"] = "Enviar contagens de falhas", ["it"] = "Invia i conteggi degli errori", ["ja"] = "失敗の件数を送る", ["zh"] = "发送失败计数", ["hi"] = "विफलताओं की गिनती भेजें", ["ar"] = "أرسل أعداد الإخفاقات" },
        ["ns.pr.show"] = new() { ["en"] = "Show what would be sent", ["es"] = "Mostrar lo que se enviaría", ["fr"] = "Montrer ce qui serait envoyé", ["de"] = "Zeigen, was gesendet würde", ["pt"] = "Mostrar o que seria enviado", ["it"] = "Mostra ciò che verrebbe inviato", ["ja"] = "送られる内容を表示", ["zh"] = "查看将要发送的内容", ["hi"] = "जो भेजा जाएगा वह दिखाएँ", ["ar"] = "أظهر ما سيُرسل" },
        ["ns.pr.hide"] = new() { ["en"] = "Hide what would be sent", ["es"] = "Ocultar lo que se enviaría", ["fr"] = "Masquer ce qui serait envoyé", ["de"] = "Verbergen, was gesendet würde", ["pt"] = "Ocultar o que seria enviado", ["it"] = "Nascondi ciò che verrebbe inviato", ["ja"] = "送られる内容を隠す", ["zh"] = "隐藏将要发送的内容", ["hi"] = "जो भेजा जाएगा वह छिपाएँ", ["ar"] = "أخفِ ما سيُرسل" },
        ["ns.pr.owed"] = new() { ["en"] = "Nothing is owed. Either nothing has failed, or everything that has was already reported.", ["es"] = "No hay nada pendiente. O no ha fallado nada, o todo lo que falló ya se informó.", ["fr"] = "Rien n'est dû. Soit rien n'a échoué, soit tout ce qui a échoué a déjà été signalé.", ["de"] = "Es steht nichts aus. Entweder ist nichts fehlgeschlagen, oder alles Fehlgeschlagene wurde bereits gemeldet.", ["pt"] = "Não há nada em dívida. Ou nada falhou, ou tudo o que falhou já foi reportado.", ["it"] = "Non c'è nulla in sospeso. O non è fallito nulla, o tutto ciò che è fallito è già stato segnalato.", ["ja"] = "送るべきものはありません。何も失敗していないか、失敗したものはすべて報告済みです。", ["zh"] = "没有待发送的内容。要么什么都没失败，要么失败过的都已上报。", ["hi"] = "कुछ भी बकाया नहीं है। या तो कुछ विफल नहीं हुआ, या जो हुआ वह पहले ही भेजा जा चुका है।", ["ar"] = "لا شيء معلّق. إما أن شيئًا لم يخفق، وإما أن كل ما أخفق قد أُبلغ عنه سلفًا." },
        ["nc.stranger"] = new() { ["en"] = "Meet a stranger", ["es"] = "Conoce a un desconocido", ["fr"] = "Rencontrer un inconnu", ["de"] = "Jemand Fremdes treffen", ["pt"] = "Conhecer um desconhecido", ["it"] = "Incontra uno sconosciuto", ["ja"] = "見知らぬ人と会う", ["zh"] = "遇见陌生人", ["hi"] = "किसी अजनबी से मिलें", ["ar"] = "قابل شخصًا غريبًا" },
        ["nc.stranger.sub"] = new() { ["en"] = "Anonymous matchmaking — they see only your alias, and either side can end it.", ["es"] = "Emparejamiento anónimo: solo ven tu alias, y cualquiera de las dos partes puede terminarlo.", ["fr"] = "Mise en relation anonyme — l'autre ne voit que votre pseudonyme, et chacun peut y mettre fin.", ["de"] = "Anonyme Vermittlung — die andere Seite sieht nur deinen Aliasnamen, und beide können es beenden.", ["pt"] = "Emparelhamento anónimo — só veem o seu pseudónimo, e qualquer das partes pode terminar.", ["it"] = "Abbinamento anonimo: vedono solo il tuo pseudonimo, e ciascuna parte può chiudere.", ["ja"] = "匿名でのマッチングです。相手に見えるのは仮名だけで、どちらからでも終わらせられます。", ["zh"] = "匿名配对 — 对方只看得到你的化名，任一方都可以结束。", ["hi"] = "गुमनाम मिलान — उन्हें सिर्फ़ आपका उपनाम दिखता है, और कोई भी पक्ष इसे ख़त्म कर सकता है।", ["ar"] = "مطابقة مجهولة — لا يرون سوى اسمك المستعار، ولأي من الطرفين أن ينهيها." },
