        ["nc.talking"] = new() { ["en"] = "Talking with {who}", ["es"] = "Hablando con {who}", ["fr"] = "En conversation avec {who}", ["de"] = "Im Gespräch mit {who}", ["pt"] = "A falar com {who}", ["it"] = "In conversazione con {who}", ["ja"] = "{who} と会話中", ["zh"] = "正在与 {who} 交谈", ["hi"] = "{who} से बात हो रही है", ["ar"] = "تتحدّث مع {who}" },
