        ["nc.tier.rated"] = new() { ["en"] = "Rated 18+", ["es"] = "Clasificado 18+", ["fr"] = "Classé 18+", ["de"] = "Ab 18 freigegeben", ["pt"] = "Classificado 18+", ["it"] = "Vietato ai minori di 18", ["ja"] = "18歳以上向け", ["zh"] = "18+ 分级", ["hi"] = "18+ रेटेड", ["ar"] = "مصنّف 18+" },
        ["nc.rated.sub"] = new() { ["en"] = "The rated tier needs a verified 18+ identity. Enter your birthdate to verify — both sides of a rated match are verified adults, and messages run under the open filter.", ["es"] = "El nivel clasificado exige una identidad verificada de 18+. Introduce tu fecha de nacimiento para verificarla: en una coincidencia clasificada ambas partes son adultos verificados y los mensajes pasan por el filtro abierto.", ["fr"] = "Le palier classé exige une identité vérifiée 18+. Saisissez votre date de naissance pour la vérifier — dans une mise en relation classée, les deux parties sont des adultes vérifiés et les messages passent par le filtre ouvert.", ["de"] = "Die freigegebene Stufe verlangt eine geprüfte Identität ab 18. Gib zum Prüfen dein Geburtsdatum ein — bei einer freigegebenen Verbindung sind beide Seiten geprüfte Erwachsene, und Nachrichten laufen über den offenen Filter.", ["pt"] = "O nível classificado exige uma identidade verificada de 18+. Introduza a sua data de nascimento para verificar — num par classificado ambos os lados são adultos verificados e as mensagens passam pelo filtro aberto.", ["it"] = "Il livello vietato ai minori richiede un'identità verificata di 18+. Inserisci la tua data di nascita per verificarla: in un abbinamento di questo livello entrambe le parti sono adulti verificati e i messaggi passano dal filtro aperto.", ["ja"] = "この区分には 18 歳以上であることの確認が必要です。確認のため生年月日を入力してください。この区分のマッチングでは双方が確認済みの成人で、メッセージは開放フィルタを通ります。", ["zh"] = "该分级需要经过验证的 18 岁以上身份。请输入出生日期以验证 — 这一分级的配对双方都是已验证的成年人，消息走开放过滤。", ["hi"] = "इस स्तर के लिए सत्यापित 18+ पहचान चाहिए। सत्यापन हेतु अपनी जन्मतिथि दर्ज करें — इस स्तर के मिलान में दोनों पक्ष सत्यापित वयस्क होते हैं और संदेश खुले फ़िल्टर से गुज़रते हैं।", ["ar"] = "تتطلّب هذه الفئة هوية موثّقة لمن هم فوق 18. أدخل تاريخ ميلادك للتوثيق — في مطابقة من هذه الفئة يكون الطرفان بالغَين موثّقَين، وتمرّ الرسائل عبر المرشّح المفتوح." },
        ["nc.birthdate.ph"] = new() { ["en"] = "Birthdate (YYYY-MM-DD)", ["es"] = "Fecha de nacimiento (AAAA-MM-DD)", ["fr"] = "Date de naissance (AAAA-MM-JJ)", ["de"] = "Geburtsdatum (JJJJ-MM-TT)", ["pt"] = "Data de nascimento (AAAA-MM-DD)", ["it"] = "Data di nascita (AAAA-MM-GG)", ["ja"] = "生年月日（YYYY-MM-DD）", ["zh"] = "出生日期（YYYY-MM-DD）", ["hi"] = "जन्मतिथि (YYYY-MM-DD)", ["ar"] = "تاريخ الميلاد (سنة-شهر-يوم)" },
