        ["nc.room.sub"] = new() { ["en"] = "A group chat with you and {name}. Every profile turn is moderated; a room with a minor always runs strict.", ["es"] = "Un chat de grupo contigo y {name}. Cada turno del perfil se modera; una sala con un menor siempre va en estricto.", ["fr"] = "Une discussion de groupe avec vous et {name}. Chaque tour du profil est modéré ; un salon avec un mineur reste toujours en mode strict.", ["de"] = "Ein Gruppenchat mit dir und {name}. Jeder Zug des Profils wird moderiert; ein Raum mit einer minderjährigen Person läuft immer streng.", ["pt"] = "Uma conversa de grupo consigo e com {name}. Cada vez do perfil é moderada; uma sala com um menor corre sempre em modo estrito.", ["it"] = "Una chat di gruppo con te e {name}. Ogni turno del profilo è moderato; una stanza con un minore va sempre in modalità rigorosa.", ["ja"] = "あなたと {name} のグループチャットです。プロフィールの発話は毎回モデレーションされ、未成年がいるルームは常に厳格モードで動きます。", ["zh"] = "你和 {name} 的群聊。资料的每一次发言都经过审核；有未成年人的房间始终以严格模式运行。", ["hi"] = "आपका और {name} का समूह-चैट। प्रोफ़ाइल की हर बारी की निगरानी होती है; किसी नाबालिग वाले कक्ष में हमेशा सख़्त मोड चलता है।", ["ar"] = "محادثة جماعية بينك وبين {name}. كل دور للملف يخضع للإشراف؛ والغرفة التي فيها قاصر تعمل دائمًا بالوضع الصارم." },
