        ["ns.pr.short"] = new() { ["en"] = "Counts of what failed. Never what you typed.", ["es"] = "Recuentos de lo que falló. Nunca lo que escribiste.", ["fr"] = "Des décomptes de ce qui a échoué. Jamais ce que vous avez saisi.", ["de"] = "Zählungen des Fehlgeschlagenen. Nie, was du getippt hast.", ["pt"] = "Contagens do que falhou. Nunca o que escreveu.", ["it"] = "Conteggi di ciò che è fallito. Mai ciò che hai scritto.", ["ja"] = "失敗の件数だけです。入力した内容は決して送りません。", ["zh"] = "只有失败的计数。绝不包含你输入的内容。", ["hi"] = "सिर्फ़ विफलताओं की गिनती। आपने जो लिखा वह कभी नहीं।", ["ar"] = "أعداد لما أخفق. لا ما كتبته أبدًا." },
        ["nsig.creds.yours"] = new() { ["en"] = "Your signing credentials", ["es"] = "Tus credenciales de firma", ["fr"] = "Vos identifiants de signature", ["de"] = "Deine Signaturberechtigungen", ["pt"] = "As suas credenciais de assinatura", ["it"] = "Le tue credenziali di firma", ["ja"] = "あなたの署名用資格情報", ["zh"] = "你的签名凭据", ["hi"] = "आपके हस्ताक्षर क्रेडेंशियल", ["ar"] = "بيانات اعتماد التوقيع الخاصة بك" },
        ["nsig.none"] = new() { ["en"] = "None yet. A signature needs a passkey bound to this account.", ["es"] = "Todavía ninguna. Una firma necesita una clave de acceso vinculada a esta cuenta.", ["fr"] = "Aucun pour l'instant. Une signature exige une clé d'accès liée à ce compte.", ["de"] = "Noch keine. Eine Signatur braucht einen Passkey, der an dieses Konto gebunden ist.", ["pt"] = "Ainda nenhuma. Uma assinatura precisa de uma chave de acesso ligada a esta conta.", ["it"] = "Ancora nessuna. Una firma richiede una passkey legata a questo account.", ["ja"] = "まだありません。署名には、このアカウントに結び付いたパスキーが必要です。", ["zh"] = "还没有。签名需要一个绑定到本账号的通行密钥。", ["hi"] = "अभी कोई नहीं। हस्ताक्षर के लिए इस खाते से बँधी पासकी चाहिए।", ["ar"] = "لا شيء بعد. يحتاج التوقيع إلى مفتاح مرور مرتبط بهذا الحساب." },
        ["nsig.register"] = new() { ["en"] = "Register this device", ["es"] = "Registrar este dispositivo", ["fr"] = "Enregistrer cet appareil", ["de"] = "Dieses Gerät registrieren", ["pt"] = "Registar este dispositivo", ["it"] = "Registra questo dispositivo", ["ja"] = "この端末を登録", ["zh"] = "注册这台设备", ["hi"] = "इस डिवाइस को पंजीकृत करें", ["ar"] = "سجّل هذا الجهاز" },
        ["nsig.cansign"] = new() { ["en"] = "can sign: {levels}", ["es"] = "puede firmar: {levels}", ["fr"] = "peut signer : {levels}", ["de"] = "kann signieren: {levels}", ["pt"] = "pode assinar: {levels}", ["it"] = "può firmare: {levels}", ["ja"] = "署名可能：{levels}", ["zh"] = "可签署：{levels}", ["hi"] = "हस्ताक्षर कर सकता है: {levels}", ["ar"] = "يمكنه التوقيع: {levels}" },
        ["nsig.proofing"] = new() { ["en"] = "verified at enrolment: {level}", ["es"] = "verificado en el registro: {level}", ["fr"] = "vérifié à l'enregistrement : {level}", ["de"] = "bei der Einrichtung geprüft: {level}", ["pt"] = "verificado no registo: {level}", ["it"] = "verificato alla registrazione: {level}", ["ja"] = "登録時の確認：{level}", ["zh"] = "注册时的核验：{level}", ["hi"] = "दर्ज करते समय सत्यापित: {level}", ["ar"] = "التحقق عند التسجيل: {level}" },
        ["nsig.level.basic"] = new() { ["en"] = "basic", ["es"] = "básico", ["fr"] = "de base", ["de"] = "einfach", ["pt"] = "básico", ["it"] = "di base", ["ja"] = "基本", ["zh"] = "基础", ["hi"] = "बुनियादी", ["ar"] = "أساسي" },
        ["nsig.level.standard"] = new() { ["en"] = "standard", ["es"] = "estándar", ["fr"] = "standard", ["de"] = "standard", ["pt"] = "padrão", ["it"] = "standard", ["ja"] = "標準", ["zh"] = "标准", ["hi"] = "मानक", ["ar"] = "قياسي" },
        ["nsig.level.high"] = new() { ["en"] = "high", ["es"] = "alto", ["fr"] = "élevé", ["de"] = "hoch", ["pt"] = "alto", ["it"] = "alto", ["ja"] = "高", ["zh"] = "高", ["hi"] = "उच्च", ["ar"] = "عالٍ" },
        ["nsig.signing"] = new() { ["en"] = "What you are signing", ["es"] = "Lo que estás firmando", ["fr"] = "Ce que vous signez", ["de"] = "Was du unterschreibst", ["pt"] = "O que está a assinar", ["it"] = "Che cosa stai firmando", ["ja"] = "あなたが署名する対象", ["zh"] = "你正在签署什么", ["hi"] = "आप क्या हस्ताक्षर कर रहे हैं", ["ar"] = "ما الذي توقّعه" },
        ["nsig.hashed"] = new() { ["en"] = "This exact text is hashed into the challenge and stored with the signature. The system prompt cannot show it — no passkey prompt can — so read it here.", ["es"] = "Este texto exacto se resume en el desafío y se guarda con la firma. El aviso del sistema no puede mostrarlo — ningún aviso de clave de acceso puede —, así que léelo aquí.", ["fr"] = "Ce texte exact est haché dans le défi et conservé avec la signature. L'invite du système ne peut pas l'afficher — aucune invite de clé d'accès ne le peut —, alors lisez-le ici.", ["de"] = "Genau dieser Text wird in die Challenge gehasht und mit der Signatur gespeichert. Die Systemabfrage kann ihn nicht zeigen — keine Passkey-Abfrage kann das —, also lies ihn hier.", ["pt"] = "Este texto exato é resumido no desafio e guardado com a assinatura. O aviso do sistema não o consegue mostrar — nenhum aviso de chave de acesso consegue —, por isso leia-o aqui.", ["it"] = "Proprio questo testo viene inserito come hash nella sfida e conservato con la firma. La richiesta di sistema non può mostrarlo — nessuna richiesta di passkey può — quindi leggilo qui.", ["ja"] = "この文面そのものがチャレンジにハッシュされ、署名とともに保存されます。システムのプロンプトはそれを表示できません — どのパスキーのプロンプトにもできません — ので、ここで読んでください。", ["zh"] = "正是这段文字被哈希进挑战值并随签名一起保存。系统提示无法显示它 — 任何通行密钥提示都不能 — 所以请在这里读它。", ["hi"] = "यही सटीक पाठ चैलेंज में हैश होकर हस्ताक्षर के साथ संग्रहित होता है। सिस्टम का संकेत इसे दिखा नहीं सकता — कोई भी पासकी संकेत नहीं दिखा सकता — इसलिए इसे यहीं पढ़ें।", ["ar"] = "هذا النص بعينه يُجزّأ في التحدّي ويُحفظ مع التوقيع. لا يمكن لنافذة النظام أن تعرضه — ولا لأي نافذة مفتاح مرور — فاقرأه هنا." },
        ["nsig.means"] = new() { ["en"] = "What your signature means", ["es"] = "Qué significa tu firma", ["fr"] = "Ce que signifie votre signature", ["de"] = "Was deine Signatur bedeutet", ["pt"] = "O que significa a sua assinatura", ["it"] = "Che cosa significa la tua firma", ["ja"] = "あなたの署名が意味すること", ["zh"] = "你的签名意味着什么", ["hi"] = "आपके हस्ताक्षर का अर्थ", ["ar"] = "ماذا يعني توقيعك" },
        ["nsig.tiers"] = new() { ["en"] = "Standard and high need an identity check beyond a passkey — that is what the tier buys. Until one is recorded against your credential, only basic will sign.", ["es"] = "Estándar y alto requieren una comprobación de identidad más allá de la clave de acceso: eso es lo que compra el nivel. Hasta que se registre una contra tu credencial, solo firmará el básico.", ["fr"] = "Standard et élevé exigent une vérification d'identité au-delà de la clé d'accès — c'est ce que le palier achète. Tant qu'aucune n'est enregistrée sur votre identifiant, seul le niveau de base signera.", ["de"] = "Standard und hoch verlangen eine Identitätsprüfung über den Passkey hinaus — dafür ist die Stufe da. Solange keine für deine Berechtigung erfasst ist, signiert nur die einfache.", ["pt"] = "Padrão e alto exigem uma verificação de identidade para além da chave de acesso — é isso que o nível compra. Até que uma fique registada na sua credencial, só o básico assina.", ["it"] = "Standard e alto richiedono una verifica dell'identità oltre alla passkey: è questo che il livello compra. Finché non ne è registrata una sulla tua credenziale, firmerà solo quello di base.", ["ja"] = "標準と高は、パスキーを超える本人確認を必要とします。それがこの段階の意味です。あなたの資格情報に確認が記録されるまでは、基本のみが署名できます。", ["zh"] = "标准与高需要通行密钥之外的身份核验 — 这正是这一档所换来的。在你的凭据上记录一次核验之前，只有基础档能签。", ["hi"] = "मानक और उच्च के लिए पासकी से आगे की पहचान-जाँच चाहिए — यही इस स्तर का मोल है। जब तक आपके क्रेडेंशियल पर कोई जाँच दर्ज न हो, केवल बुनियादी ही हस्ताक्षर करेगा।", ["ar"] = "المستوى القياسي والعالي يتطلّبان تحقّقًا من الهوية يتجاوز مفتاح المرور — وهذا ما تشتريه الفئة. وإلى أن يُسجَّل تحقّق على بيانات اعتمادك، لن يوقّع سوى المستوى الأساسي." },
        ["nsig.hello"] = new() { ["en"] = "Sign with Windows Hello", ["es"] = "Firmar con Windows Hello", ["fr"] = "Signer avec Windows Hello", ["de"] = "Mit Windows Hello signieren", ["pt"] = "Assinar com Windows Hello", ["it"] = "Firma con Windows Hello", ["ja"] = "Windows Hello で署名", ["zh"] = "用 Windows Hello 签署", ["hi"] = "Windows Hello से हस्ताक्षर करें", ["ar"] = "وقّع بـ Windows Hello" },
        ["nsig.sign"] = new() { ["en"] = "Sign", ["es"] = "Firmar", ["fr"] = "Signer", ["de"] = "Signieren", ["pt"] = "Assinar", ["it"] = "Firma", ["ja"] = "署名する", ["zh"] = "签署", ["hi"] = "हस्ताक्षर करें", ["ar"] = "توقيع" },
        ["nsig.attest"] = new() { ["en"] = "I attest this is accurate and complete", ["es"] = "Declaro que esto es exacto y completo", ["fr"] = "J'atteste que ceci est exact et complet", ["de"] = "Ich bestätige, dass dies richtig und vollständig ist", ["pt"] = "Declaro que isto é exato e completo", ["it"] = "Attesto che questo è esatto e completo", ["ja"] = "これが正確かつ完全であることを表明します", ["zh"] = "我确认此内容准确且完整", ["hi"] = "मैं प्रमाणित करता/करती हूँ कि यह सटीक और पूर्ण है", ["ar"] = "أشهد أن هذا دقيق وكامل" },
        ["nsig.lookup"] = new() { ["en"] = "Look up a signature", ["es"] = "Buscar una firma", ["fr"] = "Rechercher une signature", ["de"] = "Eine Signatur nachschlagen", ["pt"] = "Procurar uma assinatura", ["it"] = "Cerca una firma", ["ja"] = "署名を照会する", ["zh"] = "查询一个签名", ["hi"] = "कोई हस्ताक्षर खोजें", ["ar"] = "ابحث عن توقيع" },
        ["nsig.sigid"] = new() { ["en"] = "Signature id", ["es"] = "Id de firma", ["fr"] = "Id de signature", ["de"] = "Signatur-Id", ["pt"] = "Id de assinatura", ["it"] = "Id di firma", ["ja"] = "署名ID", ["zh"] = "签名ID", ["hi"] = "हस्ताक्षर आईडी", ["ar"] = "معرّف التوقيع" },
        ["nsig.fetch"] = new() { ["en"] = "Fetch and re-verify", ["es"] = "Obtener y volver a verificar", ["fr"] = "Récupérer et revérifier", ["de"] = "Abrufen und erneut prüfen", ["pt"] = "Obter e verificar de novo", ["it"] = "Recupera e verifica di nuovo", ["ja"] = "取得して再検証", ["zh"] = "取回并重新验证", ["hi"] = "लाएँ और फिर से जाँचें", ["ar"] = "اجلب وأعد التحقق" },
        ["nsig.verify.other"] = new() { ["en"] = "Verify a package from elsewhere", ["es"] = "Verificar un paquete de otro sitio", ["fr"] = "Vérifier un dossier venu d'ailleurs", ["de"] = "Ein Paket von anderswo prüfen", ["pt"] = "Verificar um pacote vindo de outro lado", ["it"] = "Verifica un pacchetto proveniente da altrove", ["ja"] = "他所から届いた一式を検証する", ["zh"] = "验证来自别处的凭据包", ["hi"] = "कहीं और से आया पैकेज जाँचें", ["ar"] = "تحقّق من حزمة واردة من مكان آخر" },
        ["nsig.evidence"] = new() { ["en"] = "Evidence package (JSON)", ["es"] = "Paquete de evidencias (JSON)", ["fr"] = "Dossier de preuves (JSON)", ["de"] = "Nachweispaket (JSON)", ["pt"] = "Pacote de evidências (JSON)", ["it"] = "Pacchetto di prove (JSON)", ["ja"] = "証拠一式（JSON）", ["zh"] = "证据包（JSON）", ["hi"] = "साक्ष्य पैकेज (JSON)", ["ar"] = "حزمة الأدلة (JSON)" },
        ["nsig.evidence.sub"] = new() { ["en"] = "Paste an evidence package a counterparty handed you. It is checked against its own contents — no account, no lookup, no trust in this deployment beyond the arithmetic.", ["es"] = "Pega un paquete de evidencias que te haya entregado la otra parte. Se comprueba contra su propio contenido: sin cuenta, sin consulta, sin más confianza en este despliegue que la aritmética.", ["fr"] = "Collez un dossier de preuves qu'une contrepartie vous a remis. Il est vérifié contre son propre contenu — pas de compte, pas de recherche, aucune confiance envers ce déploiement au-delà de l'arithmétique.", ["de"] = "Füge ein Nachweispaket ein, das eine Gegenpartei dir gegeben hat. Es wird gegen seinen eigenen Inhalt geprüft — kein Konto, keine Abfrage, kein Vertrauen in diese Installation über die Rechnung hinaus.", ["pt"] = "Cole um pacote de evidências que a contraparte lhe entregou. É verificado contra o seu próprio conteúdo — sem conta, sem consulta, sem confiança nesta instalação para além da aritmética.", ["it"] = "Incolla un pacchetto di prove che una controparte ti ha consegnato. Viene verificato rispetto al proprio contenuto: nessun account, nessuna ricerca, nessuna fiducia in questa installazione oltre l'aritmetica.", ["ja"] = "相手方から渡された証拠一式を貼り付けてください。それ自身の中身に照らして検証されます — アカウントも照会も不要で、この環境に対する信頼も計算以上には要りません。", ["zh"] = "粘贴对方交给你的证据包。它会依据自身内容被核验 — 不需要账号，不需要查询，除了算术之外不需要信任这个部署。", ["hi"] = "प्रतिपक्ष द्वारा दिया गया साक्ष्य पैकेज चिपकाएँ। इसे इसकी अपनी सामग्री के विरुद्ध जाँचा जाता है — न खाता, न कोई खोज, न गणित से आगे इस परिनियोजन पर कोई भरोसा।", ["ar"] = "الصق حزمة أدلة سلّمها لك الطرف الآخر. يجري التحقق منها في ضوء محتواها نفسه — بلا حساب، وبلا استعلام، وبلا ثقة بهذا النشر أبعد من الحساب." },
        ["nsig.verify"] = new() { ["en"] = "Verify", ["es"] = "Verificar", ["fr"] = "Vérifier", ["de"] = "Prüfen", ["pt"] = "Verificar", ["it"] = "Verifica", ["ja"] = "検証する", ["zh"] = "验证", ["hi"] = "जाँचें", ["ar"] = "تحقّق" },
        ["nsig.ceremony.win"] = new() { ["en"] = "The ceremony runs in an embedded browser rather than through webauthn.dll interop — Edge already talks to Windows Hello, and nothing here has to marshal a struct by hand. It needs the deployment served over HTTPS on its own domain: WebAuthn refuses a mismatched relying party.", ["es"] = "La ceremonia se ejecuta en un navegador incrustado en vez de mediante la interoperabilidad con webauthn.dll: Edge ya habla con Windows Hello y aquí no hay que ordenar ninguna estructura a mano. Requiere que el despliegue se sirva por HTTPS en su propio dominio: WebAuthn rechaza una parte confiante que no coincide.", ["fr"] = "La cérémonie s'exécute dans un navigateur intégré plutôt que par l'interopérabilité avec webauthn.dll — Edge parle déjà à Windows Hello, et rien ici n'a à assembler une structure à la main. Elle exige que le déploiement soit servi en HTTPS sur son propre domaine : WebAuthn refuse une partie utilisatrice qui ne correspond pas.", ["de"] = "Die Zeremonie läuft in einem eingebetteten Browser statt über die webauthn.dll-Interop — Edge spricht bereits mit Windows Hello, und hier muss nichts von Hand marshalled werden. Sie verlangt, dass die Installation über HTTPS auf ihrer eigenen Domain ausgeliefert wird: WebAuthn lehnt eine nicht passende vertrauende Partei ab.", ["pt"] = "A cerimónia corre num navegador incorporado em vez da interoperabilidade com webauthn.dll — o Edge já fala com o Windows Hello e nada aqui tem de organizar uma estrutura à mão. Exige que a instalação seja servida por HTTPS no seu próprio domínio: o WebAuthn recusa uma parte confiante que não corresponda.", ["it"] = "La cerimonia gira in un browser incorporato anziché tramite l'interoperabilità con webauthn.dll: Edge parla già con Windows Hello e qui non serve assemblare a mano alcuna struttura. Richiede che l'installazione sia servita su HTTPS con un proprio dominio: WebAuthn rifiuta una parte verificante non corrispondente.", ["ja"] = "この手続きは webauthn.dll との相互運用ではなく、埋め込みブラウザで実行されます — Edge はすでに Windows Hello と話せますし、ここで構造体を手作業で受け渡す必要もありません。環境が自前のドメインで HTTPS 配信されている必要があります。WebAuthn は一致しない依拠当事者を拒否します。", ["zh"] = "这套流程运行在内嵌浏览器里，而不是通过 webauthn.dll 互操作 — Edge 本来就能与 Windows Hello 对话，这里也不必手工编排任何结构体。它要求部署以 HTTPS 服务于自有域名：WebAuthn 会拒绝不匹配的依赖方。", ["hi"] = "यह प्रक्रिया webauthn.dll इंटरऑप के बजाय एक अंतर्निहित ब्राउज़र में चलती है — Edge पहले से Windows Hello से बात करता है, और यहाँ हाथ से कोई struct सँभालनी नहीं पड़ती। इसके लिए परिनियोजन का अपने डोमेन पर HTTPS से परोसा जाना ज़रूरी है: WebAuthn बेमेल रिलाइंग पार्टी को अस्वीकार कर देता है।", ["ar"] = "يجري هذا الإجراء داخل متصفّح مضمّن بدل التعامل مع webauthn.dll — فمتصفّح Edge يتحدّث أصلًا إلى Windows Hello، ولا شيء هنا يحتاج ترتيب بنية يدويًا. ويتطلّب أن يُقدَّم النشر عبر HTTPS على نطاقه الخاص: إذ يرفض WebAuthn طرفًا معتمِدًا غير مطابق." },
        ["nsv.title"] = new() { ["en"] = "Spoken voice", ["es"] = "Voz hablada", ["fr"] = "Voix parlée", ["de"] = "Sprechstimme", ["pt"] = "Voz falada", ["it"] = "Voce parlata", ["ja"] = "話す声", ["zh"] = "语音音色", ["hi"] = "बोलने की आवाज़", ["ar"] = "الصوت المنطوق" },
        ["nsv.lead"] = new() { ["en"] = "Point this profile at a voice you made on the engine's own surface. QRME keeps the reference; the engine keeps the voice.", ["es"] = "Apunta este perfil a una voz que creaste en la superficie del motor. QRME guarda la referencia; el motor guarda la voz.", ["fr"] = "Reliez ce profil à une voix créée sur la surface du moteur. QRME garde la référence ; le moteur garde la voix.", ["de"] = "Verbinde dieses Profil mit einer Stimme, die du auf der Oberfläche der Engine erstellt hast. QRME hält die Referenz; die Engine hält die Stimme.", ["pt"] = "Aponte este perfil para uma voz criada na superfície do motor. O QRME guarda a referência; o motor guarda a voz.", ["it"] = "Collega questo profilo a una voce creata sulla superficie del motore. QRME tiene il riferimento; il motore tiene la voce.", ["ja"] = "エンジン側で作った声にこのプロフィールを結び付けます。QRMEは参照だけを持ち、声はエンジンにあります。", ["zh"] = "把这个形象指向你在引擎端创建的声音。QRME 保存引用；声音留在引擎。", ["hi"] = "इस प्रोफ़ाइल को उस आवाज़ से जोड़ें जो आपने इंजन पर बनाई। QRME संदर्भ रखता है; आवाज़ इंजन के पास रहती है।", ["ar"] = "اربط هذا الملف بصوت أنشأته على منصّة المحرّك. يحتفظ QRME بالمرجع؛ ويبقى الصوت لدى المحرّك." },
