        ["nvoi.nothing"] = new() { ["en"] = "Nothing is recorded until you say so. QRME will only learn your own voice — there is no path here for anybody else's.", ["es"] = "No se graba nada hasta que tú lo digas. QRME solo aprenderá tu propia voz: aquí no hay camino para la de nadie más.", ["fr"] = "Rien n'est enregistré tant que vous ne le dites pas. QRME n'apprendra que votre propre voix — il n'y a ici aucun chemin pour celle de quelqu'un d'autre.", ["de"] = "Es wird nichts aufgezeichnet, bis du es sagst. QRME lernt nur deine eigene Stimme — für die von jemand anderem gibt es hier keinen Weg.", ["pt"] = "Nada é gravado até que o diga. O QRME só aprenderá a sua própria voz — aqui não há caminho para a de mais ninguém.", ["it"] = "Non viene registrato nulla finché non lo dici tu. QRME imparerà solo la tua voce: qui non c'è alcuna strada per quella di qualcun altro.", ["ja"] = "あなたが許可するまで、何も録音されません。QRME が学ぶのはあなた自身の声だけで、他人の声のための経路はここにはありません。", ["zh"] = "在你说可以之前，什么都不会被录下。QRME 只学习你自己的声音 — 这里没有任何通往他人声音的路径。", ["hi"] = "जब तक आप न कहें, कुछ भी रिकॉर्ड नहीं होता। QRME केवल आपकी अपनी आवाज़ सीखेगा — यहाँ किसी और की आवाज़ के लिए कोई रास्ता नहीं है।", ["ar"] = "لا يُسجَّل شيء حتى تأذن أنت. لن يتعلّم QRME سوى صوتك أنت — ولا سبيل هنا لصوت أحد غيرك." },
        ["nvoi.attest"] = new() { ["en"] = "This is my own voice — allow enrollment", ["es"] = "Esta es mi propia voz: permitir el registro", ["fr"] = "Ceci est ma propre voix — autoriser l'enregistrement", ["de"] = "Das ist meine eigene Stimme — Erfassung erlauben", ["pt"] = "Esta é a minha própria voz — permitir o registo", ["it"] = "Questa è la mia voce — consenti la registrazione", ["ja"] = "これは私自身の声です — 登録を許可する", ["zh"] = "这是我本人的声音 — 允许采集", ["hi"] = "यह मेरी अपनी आवाज़ है — नामांकन की अनुमति दें", ["ar"] = "هذا صوتي أنا — اسمح بالتسجيل" },
        ["nvoi.tap"] = new() { ["en"] = "Tap record and talk normally — a sentence or two about your day is better material than a read-aloud paragraph.", ["es"] = "Toca grabar y habla con normalidad: una o dos frases sobre tu día son mejor material que un párrafo leído en voz alta.", ["fr"] = "Appuyez sur enregistrer et parlez normalement — une ou deux phrases sur votre journée valent mieux qu'un paragraphe lu à voix haute.", ["de"] = "Auf Aufnehmen tippen und normal sprechen — ein, zwei Sätze über deinen Tag sind besseres Material als ein vorgelesener Absatz.", ["pt"] = "Toque em gravar e fale normalmente — uma ou duas frases sobre o seu dia são melhor material do que um parágrafo lido em voz alta.", ["it"] = "Tocca registra e parla normalmente: una o due frasi sulla tua giornata sono materiale migliore di un paragrafo letto ad alta voce.", ["ja"] = "録音を押して、普段どおり話してください。今日の出来事を一、二文話すほうが、文章を読み上げるより良い素材になります。", ["zh"] = "点录音，像平常一样说话 — 关于今天的一两句话，比朗读一段文字更合适。", ["hi"] = "रिकॉर्ड दबाइए और सामान्य रूप से बोलिए — अपने दिन के बारे में एक-दो वाक्य, पढ़े गए अनुच्छेद से बेहतर सामग्री हैं।", ["ar"] = "اضغط على التسجيل وتحدّث بشكل طبيعي — جملة أو جملتان عن يومك مادة أفضل من فقرة مقروءة بصوت عالٍ." },
        ["nvoi.stays"] = new() { ["en"] = "The recording stays on this device. Only its length and turn count are sent.", ["es"] = "La grabación se queda en este dispositivo. Solo se envían su duración y el número de turnos.", ["fr"] = "L'enregistrement reste sur cet appareil. Seules sa durée et le nombre de tours sont envoyés.", ["de"] = "Die Aufnahme bleibt auf diesem Gerät. Gesendet werden nur ihre Länge und die Zahl der Sprechzüge.", ["pt"] = "A gravação fica neste dispositivo. Só o seu comprimento e a contagem de turnos são enviados.", ["it"] = "La registrazione resta su questo dispositivo. Vengono inviate solo la sua durata e il numero di turni.", ["ja"] = "録音はこの端末に残ります。送られるのはその長さと発話回数だけです。", ["zh"] = "录音留在这台设备上。只有它的时长和轮次数会被发送。", ["hi"] = "रिकॉर्डिंग इसी डिवाइस पर रहती है। केवल उसकी लंबाई और बारी-गिनती भेजी जाती है।", ["ar"] = "يبقى التسجيل على هذا الجهاز. ولا يُرسل سوى طوله وعدد الأدوار." },
