        ["nvoi.withdraw"] = new() { ["en"] = "Withdraw consent — delete the samples, retire the voice", ["es"] = "Retirar el consentimiento: borrar las muestras, retirar la voz", ["fr"] = "Retirer le consentement — supprimer les échantillons, retirer la voix", ["de"] = "Einwilligung zurückziehen — die Proben löschen, die Stimme stilllegen", ["pt"] = "Retirar o consentimento — apagar as amostras, retirar a voz", ["it"] = "Ritira il consenso: elimina i campioni, ritira la voce", ["ja"] = "同意を撤回する — サンプルを削除し、声を停止する", ["zh"] = "撤回同意 — 删除样本，停用这把声音", ["hi"] = "सहमति वापस लें — नमूने मिटाएँ, आवाज़ निवृत्त करें", ["ar"] = "اسحب الموافقة — احذف العيّنات وأوقف الصوت" },
