        ["nvoi.holds.own"] = new() { ["en"] = "· Only your own voice — the permission is an attestation, not a checkbox.", ["es"] = "· Solo tu propia voz: el permiso es una declaración, no una casilla.", ["fr"] = "· Seulement votre propre voix — l'autorisation est une attestation, pas une case à cocher.", ["de"] = "· Nur deine eigene Stimme — die Erlaubnis ist eine Erklärung, kein Häkchen.", ["pt"] = "· Só a sua própria voz — a permissão é uma declaração, não uma caixa.", ["it"] = "· Solo la tua voce: il permesso è una dichiarazione, non una casella.", ["ja"] = "· あなた自身の声だけ — この許可はチェックボックスではなく表明です。", ["zh"] = "· 只有你自己的声音 — 这个许可是一次声明，不是一个勾选框。", ["hi"] = "· केवल आपकी अपनी आवाज़ — यह अनुमति एक घोषणा है, चेकबॉक्स नहीं।", ["ar"] = "· صوتك أنت فقط — الإذن إقرار لا مربّع اختيار." },
        ["nvoi.holds.mark"] = new() { ["en"] = "· Anything spoken in this voice carries a watermark and says it is synthesized.", ["es"] = "· Todo lo dicho con esta voz lleva una marca de agua y declara que es sintetizado.", ["fr"] = "· Tout ce qui est dit avec cette voix porte un filigrane et déclare être synthétisé.", ["de"] = "· Alles, was mit dieser Stimme gesprochen wird, trägt ein Wasserzeichen und sagt, dass es erzeugt ist.", ["pt"] = "· Tudo o que for dito com esta voz leva uma marca de água e declara ser sintetizado.", ["it"] = "· Tutto ciò che è detto con questa voce porta una filigrana e dichiara di essere sintetizzato.", ["ja"] = "· この声で話された内容にはすべて透かしが入り、合成であることを明示します。", ["zh"] = "· 用这把声音说出的一切都带有水印，并声明自己是合成的。", ["hi"] = "· इस आवाज़ में कही गई हर बात पर वॉटरमार्क रहता है और वह बताती है कि वह संश्लेषित है।", ["ar"] = "· كل ما يُقال بهذا الصوت يحمل علامة مائية ويصرّح بأنه مُصطنع." },
        ["nvoi.holds.withdraw"] = new() { ["en"] = "· Withdrawing deletes the samples and silences the voice; the withdrawal stays on record.", ["es"] = "· Retirarlo borra las muestras y silencia la voz; la retirada queda registrada.", ["fr"] = "· Le retrait supprime les échantillons et fait taire la voix ; le retrait reste consigné.", ["de"] = "· Der Widerruf löscht die Proben und legt die Stimme still; der Widerruf bleibt aktenkundig.", ["pt"] = "· Retirar apaga as amostras e silencia a voz; a retirada fica registada.", ["it"] = "· Il ritiro elimina i campioni e zittisce la voce; il ritiro resta agli atti.", ["ja"] = "· 撤回するとサンプルは削除され、声は使えなくなります。撤回そのものは記録に残ります。", ["zh"] = "· 撤回会删除样本并让这把声音沉默；撤回本身留在记录里。", ["hi"] = "· वापस लेने पर नमूने मिट जाते हैं और आवाज़ चुप हो जाती है; वापसी अभिलेख में बनी रहती है।", ["ar"] = "· السحب يحذف العيّنات ويُسكت الصوت؛ ويبقى السحب نفسه مسجَّلًا." },
        ["nvoi.retired"] = new() { ["en"] = "A previous voiceprint was retired when consent was withdrawn. That record stays.", ["es"] = "Una huella de voz anterior se retiró al retirarse el consentimiento. Ese registro permanece.", ["fr"] = "Une empreinte vocale antérieure a été retirée lors du retrait du consentement. Cette trace demeure.", ["de"] = "Ein früherer Stimmabdruck wurde stillgelegt, als die Einwilligung zurückgezogen wurde. Dieser Eintrag bleibt.", ["pt"] = "Uma impressão de voz anterior foi retirada quando o consentimento foi retirado. Esse registo permanece.", ["it"] = "Un'impronta vocale precedente è stata ritirata al ritiro del consenso. Quel registro resta.", ["ja"] = "同意が撤回された際に、以前の声紋は停止されました。その記録は残ります。", ["zh"] = "此前的一份声纹在同意被撤回时已停用。那条记录会留下。", ["hi"] = "सहमति वापस लेने पर पिछली वाणी-छाप निवृत्त कर दी गई थी। वह अभिलेख बना रहता है।", ["ar"] = "أُوقفت بصمة صوتية سابقة عند سحب الموافقة. ويبقى ذلك السجل." },
