        ["nmg.wellbeing.head"] = new() { ["en"] = "Wellbeing & quick browse", ["es"] = "Bienestar y exploración rápida", ["fr"] = "Bien-être et parcours rapide", ["de"] = "Wohlbefinden & schnelles Stöbern", ["pt"] = "Bem-estar e exploração rápida", ["it"] = "Benessere e sfoglia rapida", ["ja"] = "ウェルビーイングとクイック閲覧", ["zh"] = "健康与快速浏览", ["hi"] = "कल्याण और त्वरित अवलोकन", ["ar"] = "العافية والتصفّح السريع" },
        ["nmg.packs"] = new() { ["en"] = "Knowledge packs", ["es"] = "Paquetes de conocimiento", ["fr"] = "Recueils de connaissances", ["de"] = "Wissenspakete", ["pt"] = "Pacotes de conhecimento", ["it"] = "Raccolte di conoscenza", ["ja"] = "知識パック", ["zh"] = "知识包", ["hi"] = "ज्ञान पैक", ["ar"] = "حزم المعرفة" },
        ["nmg.packs.sub"] = new() { ["en"] = "Make this profile smarter: a pack's curated items join its source material, grounding what it knows — and every reply's provenance shows the pack honestly. 🤖 Robot task packs teach the body this profile embodies new commandable tasks, capability-checked at install. Free packs download; priced packs are bought.", ["es"] = "Haz este perfil más listo: los elementos seleccionados de un paquete se suman a su material de origen y fundamentan lo que sabe — y la procedencia de cada respuesta muestra el paquete con honestidad. 🤖 Los paquetes de tareas robóticas enseñan al cuerpo que este perfil encarna nuevas tareas ordenables, con la capacidad comprobada al instalar. Los paquetes gratuitos se descargan; los de pago se compran.", ["fr"] = "Rendez ce profil plus savant : les éléments choisis d'un recueil rejoignent son matériau source et fondent ce qu'il sait — et la provenance de chaque réponse indique honnêtement le recueil. 🤖 Les recueils de tâches robotiques apprennent au corps qu'incarne ce profil de nouvelles tâches commandables, dont la capacité est vérifiée à l'installation. Les recueils gratuits se téléchargent ; les recueils payants s'achètent.", ["de"] = "Mach dieses Profil klüger: Die kuratierten Einträge eines Pakets kommen zu seinem Quellmaterial hinzu und untermauern, was es weiß — und die Herkunft jeder Antwort nennt das Paket ehrlich. 🤖 Roboter-Aufgabenpakete bringen dem Körper, den dieses Profil verkörpert, neue befehlbare Aufgaben bei; die Fähigkeit wird bei der Installation geprüft. Kostenlose Pakete werden heruntergeladen, kostenpflichtige gekauft.", ["pt"] = "Torne este perfil mais capaz: os itens escolhidos de um pacote juntam-se ao seu material de origem e fundamentam o que sabe — e a proveniência de cada resposta mostra o pacote honestamente. 🤖 Os pacotes de tarefas robóticas ensinam ao corpo que este perfil encarna novas tarefas comandáveis, com a capacidade verificada na instalação. Os pacotes gratuitos são descarregados; os pagos são comprados.", ["it"] = "Rendi questo profilo più preparato: gli elementi selezionati di una raccolta si uniscono al suo materiale di partenza e fondano ciò che sa — e la provenienza di ogni risposta indica onestamente la raccolta. 🤖 Le raccolte di compiti robotici insegnano al corpo che questo profilo incarna nuovi compiti comandabili, con la capacità verificata all'installazione. Le raccolte gratuite si scaricano; quelle a pagamento si acquistano.", ["ja"] = "このプロフィールを賢くします。パックの厳選された項目がソース資料に加わり、知っていることの裏づけになります — そして、どの返答の来歴にもそのパックが正直に示されます。🤖 ロボット用のタスクパックは、このプロフィールが宿る身体に新しい指示可能な作業を教えます（導入時に能力を確認します）。無料のパックはダウンロード、有料のパックは購入です。", ["zh"] = "让这个资料更聪明：知识包中经过挑选的条目会并入它的源材料，为它所知的内容提供依据 — 而且每条回复的来源都会如实标明该知识包。🤖 机器人任务包会教会这个资料所栖身的躯体新的可指令任务，安装时会核验能力。免费的包可下载，收费的包需购买。", ["hi"] = "इस प्रोफ़ाइल को और समझदार बनाएँ: किसी पैक की चुनी हुई सामग्री उसके स्रोत-सामग्री में जुड़ जाती है और वह जो जानती है उसे आधार देती है — और हर उत्तर का उद्गम उस पैक को ईमानदारी से दिखाता है। 🤖 रोबोट टास्क पैक उस शरीर को, जिसमें यह प्रोफ़ाइल बसती है, नए आदेश-योग्य काम सिखाते हैं; स्थापना के समय क्षमता जाँची जाती है। मुफ़्त पैक डाउनलोड होते हैं, सशुल्क पैक ख़रीदे जाते हैं।", ["ar"] = "اجعل هذا الملف أعلم: تنضم عناصر الحزمة المنتقاة إلى مواده المصدرية فتُسنِد ما يعرفه — ويبيّن أصلُ كل ردّ الحزمةَ بأمانة. 🤖 وحزم المهام الآلية تعلّم الجسدَ الذي يتجسّد فيه هذا الملف مهامّ جديدة قابلة للأمر، مع التحقق من القدرة عند التثبيت. الحزم المجانية تُنزَّل، والمدفوعة تُشترى." },
        ["nmg.packs.sources"] = new() { ["en"] = "Pack sources", ["es"] = "Fuentes de paquetes", ["fr"] = "Sources de recueils", ["de"] = "Paketquellen", ["pt"] = "Fontes de pacotes", ["it"] = "Fonti delle raccolte", ["ja"] = "パックの提供元", ["zh"] = "知识包来源", ["hi"] = "पैक स्रोत", ["ar"] = "مصادر الحزم" },
        ["nmg.packs.sources.sub"] = new() { ["en"] = "Federated mod storefronts — sync a source and its catalog joins the marketplace, origin on every item.", ["es"] = "Tiendas de mods federadas: sincroniza una fuente y su catálogo se suma al mercado, con el origen en cada elemento.", ["fr"] = "Boutiques de mods fédérées — synchronisez une source et son catalogue rejoint la place de marché, l'origine indiquée sur chaque élément.", ["de"] = "Föderierte Mod-Shops — synchronisiere eine Quelle, und ihr Katalog kommt in den Marktplatz, die Herkunft an jedem Element.", ["pt"] = "Lojas de mods federadas — sincronize uma fonte e o seu catálogo junta-se ao mercado, com a origem em cada item.", ["it"] = "Vetrine di mod federate: sincronizza una fonte e il suo catalogo entra nel mercato, con l'origine su ogni elemento.", ["ja"] = "連合型の MOD ストアです。提供元を同期すると、そのカタログがマーケットに加わり、各項目に出所が付きます。", ["zh"] = "联邦式的模组商店 — 同步一个来源，它的目录就并入市场，每个条目都带着出处。", ["hi"] = "फ़ेडरेटेड मॉड स्टोर — किसी स्रोत को सिंक करें और उसकी सूची बाज़ार में जुड़ जाती है, हर वस्तु पर उसका मूल दर्ज रहता है।", ["ar"] = "متاجر تعديلات متّحدة — زامِن مصدرًا فينضم فهرسه إلى السوق، مع بيان الأصل على كل عنصر." },
        ["nmg.packs.synced"] = new() { ["en"] = "Synced", ["es"] = "Sincronizado", ["fr"] = "Synchronisé", ["de"] = "Synchronisiert", ["pt"] = "Sincronizado", ["it"] = "Sincronizzato", ["ja"] = "同期済み", ["zh"] = "已同步", ["hi"] = "सिंक किया गया", ["ar"] = "مُزامَن" },
        ["nmg.packs.count"] = new() { ["en"] = "{synced}/{available} packs synced", ["es"] = "{synced}/{available} paquetes sincronizados", ["fr"] = "{synced}/{available} recueils synchronisés", ["de"] = "{synced}/{available} Pakete synchronisiert", ["pt"] = "{synced}/{available} pacotes sincronizados", ["it"] = "{synced}/{available} raccolte sincronizzate", ["ja"] = "{available} 件中 {synced} 件のパックを同期済み", ["zh"] = "已同步 {synced}/{available} 个知识包", ["hi"] = "{available} में से {synced} पैक सिंक", ["ar"] = "زُومنت {synced} من {available} حزمة" },
        ["nmg.license"] = new() { ["en"] = "License this expertise", ["es"] = "Licencia esta pericia", ["fr"] = "Concéder cette expertise sous licence", ["de"] = "Diese Fachkunde lizenzieren", ["pt"] = "Licenciar esta perícia", ["it"] = "Concedi in licenza questa competenza", ["ja"] = "この専門性をライセンスする", ["zh"] = "为这份专长授权", ["hi"] = "इस विशेषज्ञता का लाइसेंस दें", ["ar"] = "رخّص هذه الخبرة" },
        ["nmg.license.sub"] = new() { ["en"] = "consult = use as-is · finetune / clone = buyers may derive their own agent (provenance recorded). Buyers acquire with their own verified identity, outside this app.", ["es"] = "consulta = usar tal cual · ajuste / clon = los compradores pueden derivar su propio agente (con la procedencia registrada). Los compradores adquieren con su propia identidad verificada, fuera de esta app.", ["fr"] = "consultation = usage tel quel · affinage / clone = les acheteurs peuvent dériver leur propre agent (provenance consignée). Les acheteurs acquièrent avec leur propre identité vérifiée, hors de cette application.", ["de"] = "Beratung = unverändert nutzen · Feinabstimmung / Klon = Käufer dürfen einen eigenen Agenten ableiten (Herkunft wird festgehalten). Käufer erwerben mit ihrer eigenen geprüften Identität, außerhalb dieser App.", ["pt"] = "consulta = usar tal como está · afinação / clone = os compradores podem derivar o seu próprio agente (a proveniência fica registada). Os compradores adquirem com a sua própria identidade verificada, fora desta aplicação.", ["it"] = "consulenza = usare così com'è · messa a punto / clone = gli acquirenti possono derivare un proprio agente (con la provenienza registrata). Gli acquirenti acquistano con la propria identità verificata, fuori da questa app.", ["ja"] = "相談＝そのまま利用 · ファインチューン／クローン＝購入者が自分のエージェントを派生させられます（来歴は記録されます）。購入は本アプリの外で、購入者自身の確認済みの身元で行われます。", ["zh"] = "咨询＝按原样使用 · 微调／克隆＝买方可派生自己的代理（来源会被记录）。买方以自己经过验证的身份在本应用之外完成购买。", ["hi"] = "परामर्श = जैसा है वैसा उपयोग · फ़ाइनट्यून / क्लोन = ख़रीदार अपना एजेंट बना सकते हैं (उद्गम दर्ज होता है)। ख़रीदार अपनी सत्यापित पहचान से, इस ऐप के बाहर ख़रीदते हैं।", ["ar"] = "الاستشارة = استخدام كما هو · الضبط الدقيق / الاستنساخ = يجوز للمشترين اشتقاق وكيل خاص بهم (يُسجَّل الأصل). ويقتني المشترون بهويتهم الموثّقة، خارج هذا التطبيق." },
