        ["nstu.sub"] = new() { ["en"] = "Send your profile out to study. Private names are redacted from everything outbound; findings come home for you to fold in.", ["es"] = "Envía tu perfil a estudiar. Los nombres privados se tachan de todo lo que sale; los hallazgos vuelven para que tú los incorpores.", ["fr"] = "Envoyez votre profil étudier. Les noms privés sont caviardés de tout ce qui sort ; les découvertes reviennent pour que vous les intégriez.", ["de"] = "Schick dein Profil zum Lernen aus. Private Namen werden aus allem Ausgehenden geschwärzt; die Funde kommen zurück, damit du sie einarbeitest.", ["pt"] = "Envie o seu perfil a estudar. Os nomes privados são ocultados de tudo o que sai; os achados voltam para que os incorpore.", ["it"] = "Manda il tuo profilo a studiare. I nomi privati vengono oscurati da tutto ciò che esce; i risultati tornano perché tu li integri.", ["ja"] = "プロフィールを学びに送り出します。外に出るものからは私的な名前が伏せられ、得られたことは持ち帰られて、あなたが取り込みます。", ["zh"] = "把你的资料派出去学习。外发的一切都会遮去私人姓名；所得会带回来，由你决定是否并入。", ["hi"] = "अपनी प्रोफ़ाइल को अध्ययन पर भेजिए। बाहर जाने वाली हर चीज़ से निजी नाम हटा दिए जाते हैं; जो मिलता है वह लौट आता है, ताकि आप उसे शामिल कर सकें।", ["ar"] = "أرسِل ملفك ليتعلّم. تُحجب الأسماء الخاصة من كل ما يخرج، وتعود النتائج إليك لتضمّها." },
        ["nstu.go"] = new() { ["en"] = "Go study", ["es"] = "Ir a estudiar", ["fr"] = "Aller étudier", ["de"] = "Losstudieren", ["pt"] = "Ir estudar", ["it"] = "Vai a studiare", ["ja"] = "学びに行く", ["zh"] = "去学习", ["hi"] = "अध्ययन पर जाएँ", ["ar"] = "اذهب للتعلّم" },
