        ["nstu.question.ph"] = new() { ["en"] = "What should it find out?", ["es"] = "¿Qué debería averiguar?", ["fr"] = "Que doit-il découvrir ?", ["de"] = "Was soll es herausfinden?", ["pt"] = "O que deve descobrir?", ["it"] = "Cosa dovrebbe scoprire?", ["ja"] = "何を調べますか？", ["zh"] = "要弄清楚什么？", ["hi"] = "क्या पता लगाए?", ["ar"] = "ما الذي يكتشفه؟" },
        ["prob.been"] = new() { ["en"] = "Where this deployment has been", ["es"] = "Dónde ha estado esta instalación", ["fr"] = "Où ce déploiement est allé", ["de"] = "Wo diese Installation war", ["pt"] = "Onde esta instalação esteve", ["it"] = "Dove è stata questa installazione", ["ja"] = "この配備が行った先", ["zh"] = "此部署去过哪里", ["hi"] = "यह परिनियोजन कहाँ-कहाँ गया", ["ar"] = "أين ذهب هذا النشر" },
        ["prob.been.pitch"] = new() { ["en"] = "Every far host this address has been seen leaving for, and how often. Hosts and counts only: no profile appears here.", ["es"] = "Cada host externo hacia el que se ha visto salir esta dirección, y con qué frecuencia. Solo hosts y recuentos: aquí no aparece ningún perfil.", ["fr"] = "Chaque hôte distant vers lequel cette adresse a été vue partir, et combien de fois. Hôtes et compteurs seulement : aucun profil n'apparaît ici.", ["de"] = "Jeder ferne Host, zu dem diese Adresse aufbrechen gesehen wurde, und wie oft. Nur Hosts und Zahlen: hier erscheint kein Profil.", ["pt"] = "Cada host distante para o qual este endereço foi visto a sair, e com que frequência. Apenas hosts e contagens: nenhum perfil aparece aqui.", ["it"] = "Ogni host remoto verso cui questo indirizzo è stato visto partire, e quante volte. Solo host e conteggi: qui non compare alcun profilo.", ["ja"] = "このアドレスが出ていった先の遠隔ホストと、その回数。ホストと件数だけで、プロフィールはここに現れません。", ["zh"] = "这个地址被看到前往的每一个远端主机及次数。只有主机和计数：这里不出现任何资料。", ["hi"] = "यह पता जिन-जिन दूरस्थ होस्ट की ओर जाते देखा गया, और कितनी बार। केवल होस्ट और गिनती: यहाँ कोई प्रोफ़ाइल नहीं आती।", ["ar"] = "كل مضيف بعيد شوهد هذا العنوان يقصده، وكم مرة. مضيفات وأعداد فقط: لا يظهر هنا أي ملف." },
        ["esc.arm"] = new() { ["en"] = "Sign the waiver", ["es"] = "Firmar la exención", ["fr"] = "Signer la décharge", ["de"] = "Verzichtserklärung unterschreiben", ["pt"] = "Assinar a declaração", ["it"] = "Firma la liberatoria", ["ja"] = "免責文に署名する", ["zh"] = "签署免责声明", ["hi"] = "छूट-पत्र पर हस्ताक्षर करें", ["ar"] = "وقّع الإقرار" },
        ["esc.sig.ph"] = new() { ["en"] = "the signature id from the signing ceremony", ["es"] = "el id de firma de la ceremonia", ["fr"] = "l'identifiant de signature issu de la cérémonie", ["de"] = "die Signatur-ID aus der Zeremonie", ["pt"] = "o id de assinatura da cerimónia", ["it"] = "l'id della firma dalla cerimonia", ["ja"] = "署名手続きで得た署名ID", ["zh"] = "签署流程返回的签名 ID", ["hi"] = "हस्ताक्षर प्रक्रिया से मिला हस्ताक्षर आईडी", ["ar"] = "معرّف التوقيع من مراسم التوقيع" },
        ["esc.hdr"] = new() { ["en"] = "When it cannot resolve it", ["es"] = "Cuando no puede resolverlo", ["fr"] = "Quand il ne peut pas résoudre", ["de"] = "Wenn es das nicht lösen kann", ["pt"] = "Quando não consegue resolver", ["it"] = "Quando non riesce a risolverlo", ["ja"] = "解決できないとき", ["zh"] = "当它无法解决时", ["hi"] = "जब यह हल न कर सके", ["ar"] = "حين لا يستطيع الحل" },
        ["esc.pitch"] = new() { ["en"] = "This profile can hand a matter to somebody real, and — if it comes to it — reach emergency services. Both are yours to press; neither happens on the profile's own judgement. Read what the waiver says now, in your own time, so that pressing it later is one press.", ["es"] = "Este perfil puede pasar un asunto a alguien real y, si llega el caso, contactar con los servicios de emergencia. Ambos los pulsas tú; ninguno ocurre por decisión del perfil. Lee ahora, con calma, lo que dice la exención, para que pulsarlo luego sea una sola pulsación.", ["fr"] = "Ce profil peut confier une affaire à quelqu'un de réel et, s'il le faut, joindre les services d'urgence. C'est vous qui appuyez ; rien ne se déclenche sur le jugement du profil. Lisez maintenant, à votre rythme, ce que dit la décharge, pour qu'appuyer plus tard soit une seule pression.", ["de"] = "Dieses Profil kann eine Sache an jemanden Echten übergeben und — wenn es sein muss — den Rettungsdienst erreichen. Beides drückst du; nichts geschieht nach dem Urteil des Profils. Lies jetzt in Ruhe, was die Verzichtserklärung sagt, damit späteres Drücken ein Druck ist.", ["pt"] = "Este perfil pode passar um assunto a alguém real e, se for preciso, contactar os serviços de emergência. É você que prime; nada acontece por decisão do perfil. Leia agora, com calma, o que diz a declaração, para que primir depois seja uma só vez.", ["it"] = "Questo profilo può passare una faccenda a qualcuno di reale e, se serve, raggiungere i servizi di emergenza. Premi tu; nulla accade per giudizio del profilo. Leggi adesso, con calma, cosa dice la liberatoria, così premere dopo è una sola pressione.", ["ja"] = "このプロフィールは用件を実在の人に引き継げますし、必要なら緊急サービスにも connect します。どちらもあなたが押すもので、プロフィールの判断では起こりません。免責文をいま落ち着いて読んでおけば、あとで押すのは一度で済みます。", ["zh"] = "这个资料可以把事情交给真实的人，必要时还能联系紧急服务。两者都由你来按；都不会依资料自己的判断发生。现在从容读一遍免责声明，这样以后按下去就只是一次按压。", ["hi"] = "यह प्रोफ़ाइल मामला किसी असली व्यक्ति को सौंप सकती है और, ज़रूरत पड़ी तो, आपातकालीन सेवाओं तक पहुँच सकती है। दोनों आप दबाते हैं; कोई भी प्रोफ़ाइल के अपने निर्णय से नहीं होता। छूट-पत्र अभी इत्मीनान से पढ़ लीजिए, ताकि बाद में दबाना बस एक दबाव हो।", ["ar"] = "هذا الملف يستطيع تسليم مسألة إلى شخص حقيقي، وإن لزم الأمر الوصول إلى خدمات الطوارئ. أنت من يضغط في الحالتين؛ ولا يحدث أي منهما بحكم الملف نفسه. اقرأ الآن، على مهلك، ما يقوله الإقرار، ليكون الضغط لاحقًا ضغطة واحدة." },
        ["esc.show"] = new() { ["en"] = "What can it do?", ["es"] = "¿Qué puede hacer?", ["fr"] = "Que peut-il faire ?", ["de"] = "Was kann es?", ["pt"] = "O que pode fazer?", ["it"] = "Cosa può fare?", ["ja"] = "何ができますか", ["zh"] = "它能做什么？", ["hi"] = "यह क्या कर सकता है?", ["ar"] = "ماذا يستطيع أن يفعل؟" },
        ["esc.armed"] = new() { ["en"] = "Signed — the press would be answered.", ["es"] = "Firmado: la pulsación sería atendida.", ["fr"] = "Signé — l'appui serait pris en compte.", ["de"] = "Unterschrieben — der Druck würde beantwortet.", ["pt"] = "Assinado — a pressão seria atendida.", ["it"] = "Firmato: la pressione verrebbe accolta.", ["ja"] = "署名済み — 押せば受け付けられます。", ["zh"] = "已签署——按下会被受理。", ["hi"] = "हस्ताक्षरित — दबाने पर स्वीकार होगा।", ["ar"] = "موقّع — سيُستجاب للضغط." },
        ["esc.notarmed"] = new() { ["en"] = "Not signed yet. Nothing here is pressed until it is.", ["es"] = "Todavía sin firmar. Aquí no se pulsa nada hasta que lo esté.", ["fr"] = "Pas encore signé. Rien ici n'est pressé tant que ce n'est pas fait.", ["de"] = "Noch nicht unterschrieben. Bis dahin wird hier nichts gedrückt.", ["pt"] = "Ainda não assinado. Nada aqui é premido até estar.", ["it"] = "Non ancora firmato. Qui non si preme nulla finché non lo è.", ["ja"] = "まだ署名されていません。署名するまで、ここでは何も押されません。", ["zh"] = "尚未签署。在签署之前，这里什么也按不下去。", ["hi"] = "अभी हस्ताक्षर नहीं। जब तक न हो, यहाँ कुछ नहीं दबता।", ["ar"] = "لم يُوقّع بعد. ولا يُضغط شيء هنا قبل ذلك." },
        ["esc.sealed"] = new() { ["en"] = "This deployment cannot place the call. Pressing it will say so and give you {number} to dial yourself — that is the beta posture, not a fault.", ["es"] = "Esta instalación no puede realizar la llamada. Al pulsarlo lo dirá y te dará {number} para que marques tú: es la postura de la beta, no un fallo.", ["fr"] = "Ce déploiement ne peut pas passer l'appel. Appuyer le dira et vous donnera {number} à composer vous-même — c'est la posture de la bêta, pas une panne.", ["de"] = "Diese Installation kann den Anruf nicht tätigen. Drücken sagt das und gibt dir {number} zum Selbstwählen — das ist die Beta-Haltung, kein Fehler.", ["pt"] = "Esta instalação não pode fazer a chamada. Primir dirá isso e dar-lhe-á {number} para marcar você — é a postura da beta, não uma avaria.", ["it"] = "Questa installazione non può effettuare la chiamata. Premere lo dirà e ti darà {number} da comporre tu — è la postura della beta, non un guasto.", ["ja"] = "この配備は通話を発信できません。押せばそう表示され、ご自分でかけるための {number} が示されます。これはベータの姿勢であり、故障ではありません。", ["zh"] = "此部署无法发出通话。按下会这样告诉你，并给出 {number} 让你自己拨——这是测试期的姿态，不是故障。", ["hi"] = "यह परिनियोजन कॉल नहीं कर सकता। दबाने पर यही बताया जाएगा और आपको स्वयं मिलाने के लिए {number} दिया जाएगा — यह बीटा की स्थिति है, खराबी नहीं।", ["ar"] = "هذا النشر لا يستطيع إجراء المكالمة. الضغط سيقول ذلك ويعطيك {number} لتتصل بنفسك — هذا وضع النسخة التجريبية، لا عطل." },
        ["esc.raise"] = new() { ["en"] = "It could not resolve this", ["es"] = "No ha podido resolverlo", ["fr"] = "Il n'a pas pu résoudre cela", ["de"] = "Es konnte das nicht lösen", ["pt"] = "Não conseguiu resolver isto", ["it"] = "Non è riuscito a risolverlo", ["ja"] = "これは解決できませんでした", ["zh"] = "它没能解决这件事", ["hi"] = "यह इसे हल नहीं कर सका", ["ar"] = "لم يستطع حلّ هذا" },
        ["esc.press"] = new() { ["en"] = "Reach emergency services", ["es"] = "Contactar con los servicios de emergencia", ["fr"] = "Joindre les services d'urgence", ["de"] = "Rettungsdienst erreichen", ["pt"] = "Contactar os serviços de emergência", ["it"] = "Raggiungi i servizi di emergenza", ["ja"] = "緊急サービスに連絡する", ["zh"] = "联系紧急服务", ["hi"] = "आपातकालीन सेवाओं तक पहुँचें", ["ar"] = "تواصل مع خدمات الطوارئ" },
        ["esc.placed"] = new() { ["en"] = "The call connected.", ["es"] = "La llamada se ha conectado.", ["fr"] = "L'appel a abouti.", ["de"] = "Der Anruf ist zustande gekommen.", ["pt"] = "A chamada foi estabelecida.", ["it"] = "La chiamata è andata a buon fine.", ["ja"] = "通話がつながりました。", ["zh"] = "通话已接通。", ["hi"] = "कॉल जुड़ गई।", ["ar"] = "تمّ الاتصال." },
        ["real.hdr"] = new() { ["en"] = "Bring somebody real into this", ["es"] = "Traer a alguien real a esto", ["fr"] = "Faire entrer quelqu'un de réel", ["de"] = "Jemanden Echten hinzuziehen", ["pt"] = "Trazer alguém real para isto", ["it"] = "Coinvolgi qualcuno di reale", ["ja"] = "誰か実在の人を呼ぶ", ["zh"] = "把真人请进来", ["hi"] = "किसी असली व्यक्ति को इसमें लाएँ", ["ar"] = "أدخِل شخصًا حقيقيًا في هذا" },
        ["real.pitch"] = new() { ["en"] = "This profile is an AI, and some things need a person. It can hand the matter to somebody real — your butcher, your broker, your doctor — and catch them up first, so you do not tell the story twice. Only what you have granted travels, and you read the whole file before anybody is contacted.", ["es"] = "Este perfil es una IA, y algunas cosas necesitan a una persona. Puede pasar el asunto a alguien real —tu carnicero, tu corredor, tu médico— y ponerle al día antes, para que no cuentes la historia dos veces. Solo viaja lo que hayas concedido, y lees el expediente entero antes de contactar con nadie.", ["fr"] = "Ce profil est une IA, et certaines choses demandent une personne. Il peut confier l'affaire à quelqu'un de réel — votre boucher, votre courtier, votre médecin — et le mettre au courant d'abord, pour que vous ne racontiez pas l'histoire deux fois. Seul ce que vous avez autorisé circule, et vous lisez le dossier entier avant que quiconque soit contacté.", ["de"] = "Dieses Profil ist eine KI, und manches braucht einen Menschen. Es kann die Sache an jemanden Echten übergeben — deinen Metzger, deinen Makler, deine Ärztin — und ihn vorher ins Bild setzen, damit du die Geschichte nicht zweimal erzählst. Es reist nur, was du freigegeben hast, und du liest die ganze Akte, bevor jemand kontaktiert wird.", ["pt"] = "Este perfil é uma IA, e algumas coisas precisam de uma pessoa. Pode passar o assunto a alguém real — o seu talhante, o seu corretor, o seu médico — e pô-lo a par primeiro, para não contar a história duas vezes. Só viaja o que autorizou, e lê o processo inteiro antes de alguém ser contactado.", ["it"] = "Questo profilo è un'IA, e certe cose hanno bisogno di una persona. Può passare la faccenda a qualcuno di reale — il tuo macellaio, il tuo broker, il tuo medico — e metterlo al corrente prima, così non racconti la storia due volte. Viaggia solo ciò che hai concesso, e leggi l'intero fascicolo prima che qualcuno venga contattato.", ["ja"] = "このプロフィールはAIで、人でなければならないこともあります。実在の人 — あなたの肉屋、仲介人、かかりつけ医 — に用件を引き継ぎ、先に事情を伝えておけるので、同じ話を二度しなくて済みます。渡るのは許可したものだけで、誰かに連絡が行く前に、あなたが資料の全部を読みます。", ["zh"] = "这个资料是 AI，有些事需要真人。它可以把事情交给真实的人——你的肉铺、你的经纪人、你的医生——并先让对方了解情况，这样你不必把事情讲两遍。只有你授权的内容会送出，而且在联系任何人之前，整份材料由你先读。", ["hi"] = "यह प्रोफ़ाइल एक AI है, और कुछ बातों के लिए इंसान चाहिए। यह मामला किसी असली व्यक्ति को सौंप सकती है — आपका कसाई, आपका दलाल, आपका डॉक्टर — और पहले उन्हें पूरी बात बता सकती है, ताकि आपको कहानी दो बार न सुनानी पड़े। केवल वही जाता है जिसकी आपने अनुमति दी, और किसी से संपर्क होने से पहले पूरी फ़ाइल आप पढ़ते हैं।", ["ar"] = "هذا الملف ذكاء اصطناعي، وبعض الأمور تحتاج إنسانًا. يمكنه تسليم المسألة إلى شخص حقيقي — جزّارك، وسيطك، طبيبك — وإطلاعه أولًا، فلا تروي القصة مرتين. لا ينتقل إلا ما أذنت به، وتقرأ الملف كاملًا قبل أن يُتصل بأحد." },
        ["real.open"] = new() { ["en"] = "Find somebody", ["es"] = "Encuentra a alguien", ["fr"] = "Trouver quelqu'un", ["de"] = "Jemanden finden", ["pt"] = "Encontre alguém", ["it"] = "Trova qualcuno", ["ja"] = "誰かを探す", ["zh"] = "找人", ["hi"] = "किसी को खोजें", ["ar"] = "ابحث عن شخص" },
