        ["real.matter.ph"] = new() { ["en"] = "what this is about, in one line", ["es"] = "de qué se trata, en una línea", ["fr"] = "de quoi il s'agit, en une ligne", ["de"] = "worum es geht, in einer Zeile", ["pt"] = "do que se trata, numa linha", ["it"] = "di che cosa si tratta, in una riga", ["ja"] = "何についてか、一行で", ["zh"] = "这是关于什么的，一行说明", ["hi"] = "यह किस बारे में है, एक पंक्ति में", ["ar"] = "موضوع هذا، في سطر واحد" },
        ["real.grant.ph"] = new() { ["en"] = "the grant that says what they may see", ["es"] = "el permiso que dice qué pueden ver", ["fr"] = "l'autorisation qui dit ce qu'ils peuvent voir", ["de"] = "die Freigabe, die sagt, was sie sehen dürfen", ["pt"] = "a autorização que diz o que podem ver", ["it"] = "il permesso che dice cosa possono vedere", ["ja"] = "相手が見てよい範囲を決める許可", ["zh"] = "决定他们可以看到什么的授权", ["hi"] = "अनुमति, जो बताती है वे क्या देख सकते हैं", ["ar"] = "التصريح الذي يحدد ما يجوز لهم رؤيته" },
        ["real.preview"] = new() { ["en"] = "Show me what would go to {name}", ["es"] = "Muéstrame qué le llegaría a {name}", ["fr"] = "Montrez-moi ce qui irait à {name}", ["de"] = "Zeig mir, was an {name} ginge", ["pt"] = "Mostre-me o que iria para {name}", ["it"] = "Mostrami cosa andrebbe a {name}", ["ja"] = "{name} に何が渡るのか見せてください", ["zh"] = "让我看看会发给 {name} 的内容", ["hi"] = "दिखाइए कि {name} को क्या जाएगा", ["ar"] = "أرِني ما الذي سيصل إلى {name}" },
        ["real.sealed"] = new() { ["en"] = "sealed in your vault", ["es"] = "sellado en tu cámara", ["fr"] = "scellé dans votre coffre", ["de"] = "in deinem Tresor versiegelt", ["pt"] = "selado no seu cofre", ["it"] = "sigillato nel tuo caveau", ["ja"] = "あなたの金庫に封じられています", ["zh"] = "封存在你的保险库中", ["hi"] = "आपकी तिजोरी में सीलबंद", ["ar"] = "مختوم في خزنتك" },
        ["rem.been"] = new() { ["en"] = "Where it keeps going back to", ["es"] = "Adónde vuelve una y otra vez", ["fr"] = "Là où il retourne sans cesse", ["de"] = "Wohin es immer wieder zurückkehrt", ["pt"] = "Aonde volta sempre", ["it"] = "Dove continua a tornare", ["ja"] = "何度も戻っている先", ["zh"] = "它一再回访的地方", ["hi"] = "यह बार-बार कहाँ लौटता है", ["ar"] = "إلى أين يعود مرارًا" },
        ["rem.been.pitch"] = new() { ["en"] = "One sanitized question tells the far end nothing. The same one every week, from the same address, tells it a rhythm and a set of interests — a subject, without a name. These are the hosts your agent has reached and how often. Only the host is kept, never the address after it.", ["es"] = "Una pregunta saneada no le dice nada al otro extremo. La misma cada semana, desde la misma dirección, le dice un ritmo y unos intereses: un sujeto, sin nombre. Estos son los hosts que ha alcanzado tu agente y con qué frecuencia. Solo se guarda el host, nunca la dirección que va después.", ["fr"] = "Une question assainie n'apprend rien à l'autre bout. La même chaque semaine, depuis la même adresse, lui apprend un rythme et des centres d'intérêt — un sujet, sans nom. Voici les hôtes que votre agent a atteints, et combien de fois. Seul l'hôte est conservé, jamais l'adresse qui suit.", ["de"] = "Eine bereinigte Frage sagt der Gegenseite nichts. Dieselbe jede Woche, von derselben Adresse, sagt ihr einen Rhythmus und eine Interessenlage — ein Subjekt, ohne Namen. Dies sind die Hosts, die dein Agent erreicht hat, und wie oft. Nur der Host wird behalten, nie die Adresse dahinter.", ["pt"] = "Uma pergunta higienizada não diz nada à outra ponta. A mesma todas as semanas, do mesmo endereço, diz-lhe um ritmo e uns interesses — um sujeito, sem nome. Estes são os hosts que o seu agente alcançou e com que frequência. Só o host é guardado, nunca o endereço a seguir.", ["it"] = "Una domanda ripulita non dice nulla all'altro capo. La stessa ogni settimana, dallo stesso indirizzo, gli dice un ritmo e degli interessi — un soggetto, senza nome. Questi sono gli host che il tuo agente ha raggiunto, e quante volte. Si conserva solo l'host, mai l'indirizzo che segue.", ["ja"] = "きれいにした質問を一度送っても、相手には何も分かりません。同じものを毎週、同じアドレスから送れば、相手には拍子と関心の範囲が分かります — 名前のない一人の対象です。以下は、あなたの助手が到達したホストと、その回数です。保存されるのはホストだけで、その先のアドレスは残しません。", ["zh"] = "一次清理过的提问不会告诉对方任何东西。每周同一个提问、来自同一个地址，就告诉了它一种节奏和一组兴趣——一个没有名字的对象。以下是你的助手到达过的主机及次数。只保留主机，绝不保留其后的地址。", ["hi"] = "एक साफ़ किया गया प्रश्न दूसरे छोर को कुछ नहीं बताता। वही प्रश्न हर हफ़्ते, उसी पते से, उसे एक लय और रुचियों का समूह बता देता है — बिना नाम का एक विषय। ये वे होस्ट हैं जहाँ आपका एजेंट पहुँचा है, और कितनी बार। केवल होस्ट रखा जाता है, उसके आगे का पता कभी नहीं।", ["ar"] = "سؤال واحد مُنقّى لا يخبر الطرف الآخر بشيء. السؤال نفسه كل أسبوع، من العنوان نفسه، يخبره بإيقاع وباهتمامات — بشخص بلا اسم. هذه هي المضيفات التي وصل إليها وكيلك، وكم مرة. يُحفظ المضيف وحده، ولا يُحفظ العنوان الذي بعده أبدًا." },
        ["rem.been.none"] = new() { ["en"] = "Your agent has not reached anywhere outside this machine.", ["es"] = "Tu agente no ha llegado a ningún sitio fuera de esta máquina.", ["fr"] = "Votre agent n'est allé nulle part hors de cette machine.", ["de"] = "Dein Agent hat nichts außerhalb dieser Maschine erreicht.", ["pt"] = "O seu agente não chegou a lado nenhum fora desta máquina.", ["it"] = "Il tuo agente non ha raggiunto nulla fuori da questa macchina.", ["ja"] = "あなたの助手は、この機械の外へは届いていません。", ["zh"] = "你的助手尚未到达本机之外的任何地方。", ["hi"] = "आपका एजेंट इस मशीन के बाहर कहीं नहीं पहुँचा है।", ["ar"] = "لم يصل وكيلك إلى أي مكان خارج هذا الجهاز." },
        ["rem.been.times"] = new() { ["en"] = "{n} visits", ["es"] = "{n} visitas", ["fr"] = "{n} visites", ["de"] = "{n} Besuche", ["pt"] = "{n} visitas", ["it"] = "{n} visite", ["ja"] = "{n}回", ["zh"] = "{n}次访问", ["hi"] = "{n} बार", ["ar"] = "{n} زيارات" },
        ["rem.been.persistent"] = new() { ["en"] = "this one has seen you enough times to know you", ["es"] = "este te ha visto suficientes veces como para conocerte", ["fr"] = "celui-ci vous a vu assez souvent pour vous connaître", ["de"] = "dieser hat dich oft genug gesehen, um dich zu kennen", ["pt"] = "este viu-o vezes suficientes para o conhecer", ["it"] = "questo ti ha visto abbastanza volte da conoscerti", ["ja"] = "ここはあなたを覚えられるだけの回数、見ています", ["zh"] = "这一个见过你的次数已足以认得你", ["hi"] = "इसने आपको इतनी बार देखा है कि यह आपको पहचान सके", ["ar"] = "هذا رآك مرات تكفي ليعرفك" },
        ["rem.been.stop"] = new() { ["en"] = "Stop visiting", ["es"] = "Dejar de visitar", ["fr"] = "Ne plus visiter", ["de"] = "Nicht mehr besuchen", ["pt"] = "Deixar de visitar", ["it"] = "Smetti di visitarlo", ["ja"] = "訪問をやめる", ["zh"] = "停止访问", ["hi"] = "जाना बंद करें", ["ar"] = "أوقف الزيارة" },
        ["rem.been.resume"] = new() { ["en"] = "Visit it again", ["es"] = "Volver a visitarlo", ["fr"] = "Le visiter de nouveau", ["de"] = "Wieder besuchen", ["pt"] = "Voltar a visitar", ["it"] = "Visitalo di nuovo", ["ja"] = "ふたたび訪問する", ["zh"] = "重新访问", ["hi"] = "फिर से जाएँ", ["ar"] = "عُد إلى زيارته" },
        ["rem.been.stopped"] = new() { ["en"] = "stopped — nothing here reaches it, on any path", ["es"] = "detenido: nada de aquí lo alcanza, por ninguna vía", ["fr"] = "arrêté — rien d'ici ne l'atteint, par aucun chemin", ["de"] = "gestoppt — von hier erreicht es nichts, auf keinem Weg", ["pt"] = "parado — nada daqui o alcança, por via nenhuma", ["it"] = "fermato: da qui non lo raggiunge nulla, per nessuna via", ["ja"] = "停止中 — どの経路からもここからは届きません", ["zh"] = "已停止——本机的任何路径都不会到达它", ["hi"] = "रुका हुआ — यहाँ से किसी भी रास्ते से वहाँ कुछ नहीं जाता", ["ar"] = "موقوف — لا شيء من هنا يصل إليه، بأي مسار" },
        ["nask"] = new() { ["en"] = "Ask people, not pages", ["es"] = "Pregunta a personas, no a páginas", ["fr"] = "Demandez à des gens, pas à des pages", ["de"] = "Menschen fragen, nicht Seiten", ["pt"] = "Pergunte a pessoas, não a páginas", ["it"] = "Chiedi alle persone, non alle pagine", ["ja"] = "ページではなく、人に聞く", ["zh"] = "问人，而不是问网页", ["hi"] = "पन्नों से नहीं, लोगों से पूछें", ["ar"] = "اسأل الناس، لا الصفحات" },
        ["nask.sub"] = new() { ["en"] = "Some things were never written down. Put the question on the open board and anyone can answer it. Your names are stripped out before it goes up.", ["es"] = "Hay cosas que nunca se escribieron. Pon la pregunta en el tablón abierto y cualquiera puede responderla. Tus nombres se quitan antes de que suba.", ["fr"] = "Certaines choses n'ont jamais été écrites. Mettez la question sur le tableau ouvert et n'importe qui peut y répondre. Vos noms sont retirés avant la mise en ligne.", ["de"] = "Manches wurde nie aufgeschrieben. Stell die Frage aufs offene Brett, und jeder kann antworten. Deine Namen werden vorher entfernt.", ["pt"] = "Há coisas que nunca foram escritas. Ponha a pergunta no quadro aberto e qualquer pessoa pode responder. Os seus nomes são retirados antes de subir.", ["it"] = "Certe cose non sono mai state scritte. Metti la domanda sulla bacheca aperta e chiunque può rispondere. I tuoi nomi vengono tolti prima che salga.", ["ja"] = "どこにも書かれなかったことがあります。公開の掲示板に質問を出せば、誰でも答えられます。あなたの名前は出る前に取り除かれます。", ["zh"] = "有些事从没被写下来过。把问题贴到公开板上，任何人都能回答。你的名字在贴出前会被剥除。", ["hi"] = "कुछ बातें कभी लिखी ही नहीं गईं। प्रश्न को खुले बोर्ड पर रखिए और कोई भी उत्तर दे सकता है। आपके नाम जाने से पहले हटा दिए जाते हैं।", ["ar"] = "بعض الأمور لم تُكتب قط. ضع السؤال على اللوحة المفتوحة فيستطيع أي أحد أن يجيب. تُحذف أسماؤك قبل أن يُنشر." },
        ["nask.q.ph"] = new() { ["en"] = "what you want to know", ["es"] = "qué quieres saber", ["fr"] = "ce que vous voulez savoir", ["de"] = "was du wissen möchtest", ["pt"] = "o que quer saber", ["it"] = "che cosa vuoi sapere", ["ja"] = "知りたいこと", ["zh"] = "你想知道什么", ["hi"] = "आप क्या जानना चाहते हैं", ["ar"] = "ما تريد معرفته" },
        ["nask.go"] = new() { ["en"] = "Put the question out", ["es"] = "Publicar la pregunta", ["fr"] = "Publier la question", ["de"] = "Die Frage aushängen", ["pt"] = "Publicar a pergunta", ["it"] = "Pubblica la domanda", ["ja"] = "質問を出す", ["zh"] = "把问题贴出去", ["hi"] = "प्रश्न सामने रखें", ["ar"] = "انشر السؤال" },
