        ["ngam.sub.full"] = new() { ["en"] = "Bring this profile into a game as a companion or teammate — agent-operated. It talks in character and moderated, and always plays within the game's rules; it never cheats.", ["es"] = "Lleva este perfil a un juego como acompañante o compañero de equipo, operado por un agente. Habla en personaje y con moderación, y siempre juega dentro de las reglas del juego: nunca hace trampas.", ["fr"] = "Amenez ce profil dans un jeu comme compagnon ou coéquipier — piloté par un agent. Il parle dans son personnage et sous modération, et joue toujours dans les règles du jeu ; il ne triche jamais.", ["de"] = "Hol dieses Profil als Begleiter oder Mitspieler in ein Spiel — von einem Agenten geführt. Es spricht in seiner Rolle und moderiert und spielt immer nach den Regeln des Spiels; es betrügt nie.", ["pt"] = "Traga este perfil para um jogo como companheiro ou colega de equipa — operado por um agente. Fala em personagem e com moderação, e joga sempre dentro das regras do jogo; nunca faz batota.", ["it"] = "Porta questo profilo in un gioco come compagno o compagno di squadra — guidato da un agente. Parla nel personaggio e con moderazione, e gioca sempre secondo le regole del gioco; non bara mai.", ["ja"] = "このプロフィールを、仲間やチームメイトとしてゲームに連れて行けます — 動かすのはエージェントです。役柄のまま、モデレーションを受けて話し、つねにゲームの規則の中で遊びます。ずるはしません。", ["zh"] = "把这个资料带进游戏，作为同伴或队友 — 由代理操作。它以角色的口吻说话并受审核，而且始终在游戏规则之内游玩，从不作弊。", ["hi"] = "इस प्रोफ़ाइल को किसी खेल में साथी या टीम-सदस्य के रूप में लाएँ — इसे एक एजेंट चलाता है। यह अपने किरदार में और संयमित होकर बात करती है, और हमेशा खेल के नियमों के भीतर खेलती है; कभी बेईमानी नहीं करती।", ["ar"] = "خُذ هذا الملف إلى لعبة رفيقًا أو زميلًا في الفريق — يشغّله وكيل. يتكلّم بشخصيته وتحت الإشراف، ويلعب دائمًا ضمن قواعد اللعبة، ولا يغشّ أبدًا." },
