        ["pub.object.needid"] = new() { ["en"] = "Enter the profile's id and your proof reference.", ["es"] = "Introduzca el id del perfil y su referencia de prueba.", ["fr"] = "Saisissez l'identifiant du profil et votre référence de preuve.", ["de"] = "Gib die Profil-ID und deine Nachweisreferenz ein.", ["pt"] = "Introduza o id do perfil e a sua referência de prova.", ["it"] = "Inserisci l'id del profilo e il tuo riferimento di prova.", ["ja"] = "プロフィールIDと証明の参照番号を入力してください。", ["zh"] = "请输入资料 id 和你的证明参考号。", ["hi"] = "प्रोफ़ाइल आईडी और अपना प्रमाण संदर्भ दर्ज करें।", ["ar"] = "أدخل معرّف الملف ومرجع إثباتك." },
